// Equipamento padrão de um exercício montado automaticamente: máquina (ex.: Smith) ou halteres primeiro;
// peso corporal só quando não há outra opção. A pessoa pode trocar depois.
function escolherEquipamentoPadrao(maquinas) {
  const lista = Array.isArray(maquinas) ? maquinas : [];
  const ordem = (m) => (/máquina|smith|hack|pêndulo|pendulo|articulado/i.test(m) ? 0 : /halter/i.test(m) ? 1 : /barra|cabo/i.test(m) ? 2 : /peso corporal/i.test(m) ? 9 : 5);
  return [...lista].sort((a, b) => ordem(a) - ordem(b))[0];
}

