// <<ASSINATURAS-INICIO>>
// ===============================================================
// ASSINATURAS — CONFIGURAÇÃO CENTRAL
// ---------------------------------------------------------------
// ✅ Tudo que é comercial fica NESTA seção: preços, teste grátis,
//    benefícios da comparação e limites mensais de IA.
//    Pra mudar um valor, mexa só aqui — a tela de planos, a economia
//    do plano anual, a comparação e o controle de uso de IA se
//    atualizam sozinhos.
// ===============================================================

const CONFIG_ASSINATURA = {
  // Dias de teste grátis de cada plano (0 desliga o teste daquele plano).
  diasTesteGratis: { pro: 7, ia: 7 },
  // true  = cada pessoa tem direito a UM teste grátis no total (Pro OU Pro IA).
  // false = cada plano tem o seu próprio teste, uma vez por pessoa.
  testeUnicoPorUsuario: true,
  // Quem cobra: "simulado" (hoje, sem cobrança real) | "googlePlay" | "appStore".
  provedorPagamento: "simulado",
  // Enquanto for false, o fim do teste NÃO bloqueia o app (ainda não existe
  // cobrança real pra fazer). Ao integrar as lojas, troque pra true: aí o plano
  // só vale enquanto a loja confirmar a assinatura.
  cobrancaRealAtiva: false,
  // Prefixo dos IDs de produto cadastrados no Google Play / App Store
  // (ficam "massipro_pro_mensal", "massipro_ia_anual" etc).
  prefixoProdutoLoja: "massipro",
};

// Os dois níveis de assinatura.
const NIVEIS_ASSINATURA = {
  pro: {
    id: "pro",
    nome: "Massi Pro",
    slogan: "Seu treino completo, organizado e personalizado.",
    selo: "COMPLETO",
    temIA: false,
  },
  ia: {
    id: "ia",
    nome: "Massi Pro IA",
    slogan: "Mais inteligência para acompanhar sua evolução.",
    selo: "PREMIUM · COM IA",
    temIA: true,
    premium: true,
  },
};

// Os períodos de cobrança. "meses" é usado pra calcular a economia do plano
// anual/semestral em relação a pagar mês a mês.
const PERIODOS_ASSINATURA = [
  { id: "mensal", nome: "Mensal", meses: 1, sufixoCurto: "/mês", sufixoCobranca: "por mês" },
  { id: "semestral", nome: "Semestral", meses: 6, sufixoCurto: "/semestre", sufixoCobranca: "a cada 6 meses" },
  { id: "anual", nome: "Anual", meses: 12, sufixoCurto: "/ano", sufixoCobranca: "por ano", destaque: true },
];

// 💰 PREÇOS — total cobrado em cada período, em reais.
// (É AQUI que se muda preço. O Google Play / App Store precisam ter o mesmo valor.)
const PRECOS_ASSINATURA = {
  pro: { mensal: 19.9, semestral: 99.9, anual: 159.9 },
  ia: { mensal: 29.9, semestral: 149.9, anual: 249.9 },
};

// 🤖 FUNÇÕES DE IA e os limites de uso por mês.
// Pra criar uma função nova de IA: adicione uma linha em RECURSOS_IA. Se ela não
// precisar de limite próprio, use `grupo: "outras"` e ela consome do limite "outras".
// `emBreve: true` mostra a etiqueta "EM BREVE" na tela de planos (tire quando lançar).
const RECURSOS_IA = {
  chat: { nome: "Assistente de IA (perguntas e comandos)", emBreve: false },
  foto: { nome: "Análise de refeição por foto", emBreve: false },
  treino: { nome: "Geração e ajuste de treino por IA", emBreve: false }, // usado pela Rotina Inteligente (plano e reavaliação)
  outras: { nome: "Outras funções de IA", emBreve: true },
};

// 📊 LIMITE MENSAL de uso de IA por plano e por função (número de usos no mês).
// 0 = o plano não inclui aquela função. Valores iniciais — ajuste quando medir o custo real.
const LIMITES_IA_MENSAL = {
  pro: { chat: 0, foto: 0, treino: 0, outras: 0 },
  ia: { chat: 100, foto: 30, treino: 10, outras: 20 },
};

// Linhas "gerais" da tabela de comparação (as de IA saem de RECURSOS_IA sozinhas).
const BENEFICIOS_COMPARACAO = [
  { texto: "Acesso completo ao app", pro: true, ia: true },
  { texto: "+1.200 dietas prontas", pro: true, ia: true },
  { texto: "Relatório mensal em PDF", pro: true, ia: true },
  { texto: "Rotinas e histórico ilimitados", pro: true, ia: true },
  { texto: "Sugestões de progressão de carga", pro: true, ia: true },
];

// ---------- Funções de apoio (não precisa mexer) ----------

const CHAVE_ASSINATURA = "assinatura-massipro"; // global: vale pra todos os perfis do aparelho
const CHAVE_USO_IA = "uso-ia-massipro"; // global: o limite é por assinatura, não por perfil
const DIA_MS = 86400000;

function formatarPreco(valor) {
  const centavos = Math.round(valor * 100 + 1e-6);
  const reais = Math.floor(centavos / 100);
  const resto = centavos % 100;
  return "R$ " + reais + "," + (resto < 10 ? "0" : "") + resto;
}

function idProdutoLoja(nivel, periodo) {
  return CONFIG_ASSINATURA.prefixoProdutoLoja + "_" + nivel + "_" + periodo;
}

// Faz o caminho inverso: "massipro_ia_anual" → { nivel: "ia", periodo: "anual" }
function lerIdProdutoLoja(produtoId) {
  if (typeof produtoId !== "string") return null;
  const partes = produtoId.split("_");
  if (partes.length !== 3 || partes[0] !== CONFIG_ASSINATURA.prefixoProdutoLoja) return null;
  if (!NIVEIS_ASSINATURA[partes[1]] || !PERIODOS_ASSINATURA.some((p) => p.id === partes[2])) return null;
  return { nivel: partes[1], periodo: partes[2] };
}

// Tudo que a tela precisa saber de um plano (nível + período), já calculado.
function infoPlano(nivel, periodo) {
  const per = PERIODOS_ASSINATURA.find((p) => p.id === periodo) || PERIODOS_ASSINATURA[0];
  const tabela = PRECOS_ASSINATURA[nivel] || PRECOS_ASSINATURA.pro;
  const total = tabela[per.id];
  const referencia = tabela.mensal * per.meses; // quanto pagaria mês a mês
  const economiaPct = per.meses > 1 && referencia > 0 ? Math.round((1 - total / referencia) * 100) : 0;
  return {
    nivel,
    periodo: per.id,
    nome: per.nome,
    meses: per.meses,
    sufixoCurto: per.sufixoCurto,
    sufixoCobranca: per.sufixoCobranca,
    destaque: !!per.destaque,
    total,
    porMes: total / per.meses,
    economiaPct,
    economiaValor: per.meses > 1 ? Math.max(0, referencia - total) : 0,
    produtoId: idProdutoLoja(nivel, per.id),
  };
}

function mesChaveAtual() {
  const d = new Date();
  const m = d.getMonth() + 1;
  return d.getFullYear() + "-" + (m < 10 ? "0" : "") + m;
}

// ---------- Estado da assinatura ----------

function assinaturaVazia() {
  return {
    nivel: null, // "pro" | "ia" | null
    periodo: null, // "mensal" | "semestral" | "anual" | null
    status: "nenhuma", // "nenhuma" | "teste" | "ativa" | "cancelada"
    inicio: null,
    testeFim: null,
    expiraEm: null, // preenchido pela loja quando a cobrança real estiver ligada
    produtoId: null,
    origem: null, // "simulado" | "googlePlay" | "appStore" | "legado"
    testesUsados: { pro: false, ia: false },
  };
}

function normalizarAssinatura(raw) {
  const base = assinaturaVazia();
  if (!raw || typeof raw !== "object") return base;
  const r = { ...base, ...raw };
  r.testesUsados = {
    pro: !!(raw.testesUsados && raw.testesUsados.pro),
    ia: !!(raw.testesUsados && raw.testesUsados.ia),
  };
  if (r.nivel && !NIVEIS_ASSINATURA[r.nivel]) {
    r.nivel = null;
    r.periodo = null;
    r.status = "nenhuma";
  }
  return r;
}

// Responde "o que essa pessoa pode usar agora?". É a ÚNICA função que decide isso.
function assinaturaVigente(est, agora) {
  const t = agora || Date.now();
  const vazio = {
    ativa: false,
    nivel: null,
    periodo: null,
    emTeste: false,
    testeEncerrado: false,
    diasRestantesTeste: 0,
    temIA: false,
    legado: false,
  };
  if (!est || !est.nivel || !NIVEIS_ASSINATURA[est.nivel]) return vazio;
  const cobrancaReal = CONFIG_ASSINATURA.cobrancaRealAtiva;
  let ativa = false;
  let emTeste = false;
  let testeEncerrado = false;
  let dias = 0;
  if (est.status === "teste") {
    const fim = est.testeFim ? Date.parse(est.testeFim) : 0;
    if (fim && t < fim) {
      ativa = true;
      emTeste = true;
      dias = Math.max(1, Math.ceil((fim - t) / DIA_MS));
    } else {
      testeEncerrado = true;
      ativa = !cobrancaReal; // sem cobrança real ainda, o app não tranca no fim do teste
    }
  } else if (est.status === "ativa") {
    ativa = true;
    if (cobrancaReal && est.expiraEm) {
      const ex = Date.parse(est.expiraEm);
      if (ex && t > ex) ativa = false;
    }
  }
  return {
    ativa,
    nivel: est.nivel,
    periodo: est.periodo || null,
    emTeste,
    testeEncerrado,
    diasRestantesTeste: dias,
    temIA: ativa && !!NIVEIS_ASSINATURA[est.nivel].temIA,
    legado: est.origem === "legado",
  };
}

function testeJaUsado(est, nivel) {
  const u = (est && est.testesUsados) || {};
  return CONFIG_ASSINATURA.testeUnicoPorUsuario ? !!(u.pro || u.ia) : !!u[nivel];
}

// Quantos dias de teste grátis esse plano oferece PRA ESSA PESSOA agora (0 = nenhum).
function diasTesteDisponivel(est, nivel) {
  const dias = (CONFIG_ASSINATURA.diasTesteGratis || {})[nivel] || 0;
  if (dias <= 0) return 0;
  return testeJaUsado(est, nivel) ? 0 : dias;
}

// Guarda o estado da assinatura, avisa a tela quando muda e migra quem já era Premium.
const StoreAssinatura = (() => {
  let estado = assinaturaVazia();
  let carregado = false;
  let carregando = null;
  const ouvintes = new Set();

  const notificar = () => {
    ouvintes.forEach((fn) => {
      try {
        fn(estado);
      } catch (e) {
        // um ouvinte com problema não derruba os outros
      }
    });
  };
  const salvar = async () => {
    try {
      await window.storage.set(CHAVE_ASSINATURA, JSON.stringify(estado));
    } catch (e) {
      // segue mesmo se salvar falhar; o estado em memória já vale
    }
  };

  async function carregar() {
    if (carregado) return estado;
    if (!carregando) {
      carregando = (async () => {
        let achou = false;
        try {
          const r = await window.storage.get(CHAVE_ASSINATURA);
          if (r && r.value) {
            estado = normalizarAssinatura(JSON.parse(r.value));
            achou = true;
          }
        } catch (e) {
          // ainda não existe
        }
        if (!achou) {
          // Migração: quem já era "Premium" na versão antiga vira Massi Pro ativo.
          try {
            const antigo = await window.storage.get("status-premium");
            if (antigo && antigo.value === "true") {
              estado = normalizarAssinatura({
                nivel: "pro",
                status: "ativa",
                inicio: new Date().toISOString(),
                origem: "legado",
              });
              await salvar();
            }
          } catch (e) {
            // sem Premium antigo
          }
        }
        carregado = true;
        notificar();
      })();
    }
    await carregando;
    return estado;
  }

  return {
    carregar,
    obter: () => estado,
    async definir(novo) {
      estado = normalizarAssinatura(novo);
      carregado = true;
      await salvar();
      notificar();
      return estado;
    },
    inscrever(fn) {
      ouvintes.add(fn);
      return () => ouvintes.delete(fn);
    },
  };
})();

// ---------- Controle de uso de IA (limite mensal por pessoa) ----------
// Qualquer função de IA — agora ou no futuro — usa SÓ esta API:
//   const r = await MassiIA.consumir("chat");   // antes de chamar a IA
//   if (!r.ok) { ...avisa (r.motivo: "sem_plano_ia" | "recurso_indisponivel" | "limite_mensal") }
//   ...se a chamada à IA falhar:  await MassiIA.devolver("chat");
const MassiIA = (() => {
  let uso = { mes: mesChaveAtual(), usos: {} };
  let carregado = false;
  let carregando = null;
  const ouvintes = new Set();

  const notificar = () => {
    ouvintes.forEach((fn) => {
      try {
        fn(uso);
      } catch (e) {
        // um ouvinte com problema não derruba os outros
      }
    });
  };
  const virouOMes = () => {
    const m = mesChaveAtual();
    if (uso.mes !== m) uso = { mes: m, usos: {} };
  };
  const grupoDe = (recursoId) => {
    const r = RECURSOS_IA[recursoId];
    return r && r.grupo ? r.grupo : recursoId;
  };
  const salvar = async () => {
    try {
      await window.storage.set(CHAVE_USO_IA, JSON.stringify(uso));
    } catch (e) {
      // segue mesmo se salvar falhar
    }
  };

  async function carregar() {
    if (carregado) return uso;
    if (!carregando) {
      carregando = (async () => {
        try {
          const r = await window.storage.get(CHAVE_USO_IA);
          if (r && r.value) {
            const lido = JSON.parse(r.value);
            if (lido && typeof lido === "object" && lido.usos && typeof lido.usos === "object") {
              uso = { mes: String(lido.mes || ""), usos: lido.usos };
            }
          }
        } catch (e) {
          // ainda não existe
        }
        virouOMes();
        carregado = true;
        notificar();
      })();
    }
    await carregando;
    return uso;
  }

  // Situação de uma função: quanto pode, quanto já usou, quanto resta.
  function situacao(recursoId) {
    virouOMes();
    const vig = assinaturaVigente(StoreAssinatura.obter());
    const grupo = grupoDe(recursoId);
    const planoComIA = vig.ativa && vig.temIA;
    const limite = planoComIA ? ((LIMITES_IA_MENSAL[vig.nivel] || {})[grupo] || 0) : 0;
    const usado = uso.usos[grupo] || 0;
    return { recurso: recursoId, grupo, planoComIA, limite, usado, restante: Math.max(0, limite - usado) };
  }

  async function consumir(recursoId, qtd) {
    await carregar();
    const q = qtd > 0 ? Math.floor(qtd) : 1;
    const s = situacao(recursoId);
    if (!s.planoComIA) return { ok: false, motivo: "sem_plano_ia", ...s };
    if (s.limite <= 0) return { ok: false, motivo: "recurso_indisponivel", ...s };
    if (s.usado + q > s.limite) return { ok: false, motivo: "limite_mensal", ...s };
    uso = { mes: uso.mes, usos: { ...uso.usos, [s.grupo]: s.usado + q } };
    notificar();
    await salvar();
    return { ok: true, motivo: null, ...situacao(recursoId) };
  }

  // Devolve o uso quando a chamada à IA deu erro (a pessoa não paga por falha).
  async function devolver(recursoId, qtd) {
    await carregar();
    virouOMes();
    const q = qtd > 0 ? Math.floor(qtd) : 1;
    const grupo = grupoDe(recursoId);
    const atual = uso.usos[grupo] || 0;
    uso = { mes: uso.mes, usos: { ...uso.usos, [grupo]: Math.max(0, atual - q) } };
    notificar();
    await salvar();
    return situacao(recursoId);
  }

  // Lista pronta pra tela: uma linha por limite (funções do grupo "outras" somam num só).
  function resumo() {
    const vistos = {};
    const lista = [];
    Object.keys(RECURSOS_IA).forEach((id) => {
      const g = grupoDe(id);
      if (vistos[g]) return;
      vistos[g] = true;
      const base = RECURSOS_IA[g] || RECURSOS_IA[id];
      const s = situacao(g);
      lista.push({ id: g, nome: base.nome, emBreve: !!base.emBreve, limite: s.limite, usado: s.usado, restante: s.restante });
    });
    return lista;
  }

  return {
    carregar,
    consumir,
    devolver,
    situacao,
    resumo,
    inscrever(fn) {
      ouvintes.add(fn);
      return () => ouvintes.delete(fn);
    },
  };
})();

// ---------- Pagamento: um "provedor" por loja, todos com a mesma cara ----------
// O resto do app só fala com provedorAtual(). Quando integrar Google Play / App Store,
// só estes provedores mudam (e CONFIG_ASSINATURA.provedorPagamento + cobrancaRealAtiva).

// Quando a LOJA confirmar uma compra/renovação/cancelamento, chame isto com os dados dela.
// Ex.: aplicarAssinaturaDaLoja({ produtoId: "massipro_ia_anual", status: "ativa",
//        expiraEm: "2027-10-08T00:00:00Z", origem: "googlePlay" })
async function aplicarAssinaturaDaLoja(info) {
  const prod = lerIdProdutoLoja(info && info.produtoId);
  if (!prod) return { ok: false, erro: "produto_desconhecido" };
  const atual = StoreAssinatura.obter();
  const status = info.status || "ativa";
  const novo = {
    ...atual,
    nivel: prod.nivel,
    periodo: prod.periodo,
    status,
    inicio: info.inicio || atual.inicio || new Date().toISOString(),
    testeFim: info.testeFim || null,
    expiraEm: info.expiraEm || null,
    produtoId: info.produtoId,
    origem: info.origem || CONFIG_ASSINATURA.provedorPagamento,
    testesUsados: { ...atual.testesUsados },
  };
  if (status === "teste") novo.testesUsados[prod.nivel] = true;
  await StoreAssinatura.definir(novo);
  return { ok: true, estado: novo };
}

const PROVEDORES_PAGAMENTO = {
  // Hoje: não cobra nada de verdade. Só registra o plano escolhido e o teste grátis no aparelho.
  simulado: {
    id: "simulado",
    nomeLoja: null,
    simulado: true,
    async iniciarAssinatura({ nivel, periodo }) {
      const est = StoreAssinatura.obter();
      const agora = Date.now();
      const vig = assinaturaVigente(est, agora);
      const diasTeste = diasTesteDisponivel(est, nivel);
      const produtoId = idProdutoLoja(nivel, periodo);
      let novo;
      if (vig.emTeste) {
        // trocou de plano durante o teste: continua o mesmo teste, sem ganhar dias extras
        novo = { ...est, nivel, periodo, produtoId };
      } else if (diasTeste > 0) {
        novo = {
          ...est,
          nivel,
          periodo,
          status: "teste",
          inicio: new Date(agora).toISOString(),
          testeFim: new Date(agora + diasTeste * DIA_MS).toISOString(),
          expiraEm: null,
          produtoId,
          origem: "simulado",
          testesUsados: { ...est.testesUsados, [nivel]: true },
        };
      } else {
        novo = {
          ...est,
          nivel,
          periodo,
          status: "ativa",
          inicio: new Date(agora).toISOString(),
          testeFim: null,
          expiraEm: null,
          produtoId,
          origem: "simulado",
        };
      }
      const salvo = await StoreAssinatura.definir(novo);
      return { ok: true, estado: salvo, comTeste: salvo.status === "teste" };
    },
    async restaurar() {
      return { ok: assinaturaVigente(StoreAssinatura.obter()).ativa };
    },
  },

  // 🔌 TODO GOOGLE PLAY BILLING (Android, via Capacitor — ex.: cordova-plugin-purchase ou RevenueCat)
  //  1) Cadastrar no Play Console as 6 assinaturas com os IDs de idProdutoLoja() e o teste de 7 dias.
  //  2) iniciarAssinatura: abrir o fluxo de compra do produtoId e, no sucesso, chamar
  //     aplicarAssinaturaDaLoja({ produtoId, status: "teste" ou "ativa", expiraEm, origem: "googlePlay" }).
  //  3) restaurar: consultar as compras da conta Google e chamar aplicarAssinaturaDaLoja com a vigente.
  //  4) Ouvir renovações/cancelamentos da loja e chamar aplicarAssinaturaDaLoja de novo.
  //  5) Trocar provedorPagamento pra "googlePlay" e cobrancaRealAtiva pra true.
  googlePlay: {
    id: "googlePlay",
    nomeLoja: "Google Play",
    simulado: false,
    async iniciarAssinatura() {
      return { ok: false, erro: "loja_nao_integrada" };
    },
    async restaurar() {
      return { ok: false, erro: "loja_nao_integrada" };
    },
  },

  // 🔌 TODO APP STORE (iOS, via Capacitor — StoreKit 2 / RevenueCat). Mesmo roteiro do Google Play,
  //    com origem: "appStore". Os produtos entram num único "grupo de assinatura" (Pro e Pro IA).
  appStore: {
    id: "appStore",
    nomeLoja: "App Store",
    simulado: false,
    async iniciarAssinatura() {
      return { ok: false, erro: "loja_nao_integrada" };
    },
    async restaurar() {
      return { ok: false, erro: "loja_nao_integrada" };
    },
  },
};

function provedorAtual() {
  return PROVEDORES_PAGAMENTO[CONFIG_ASSINATURA.provedorPagamento] || PROVEDORES_PAGAMENTO.simulado;
}

// ---------- Hooks pra tela ----------

function useAssinatura() {
  const [est, setEst] = useState(() => StoreAssinatura.obter());
  useEffect(() => {
    let vivo = true;
    StoreAssinatura.carregar().then((e) => {
      if (vivo) setEst(e);
    });
    const sair = StoreAssinatura.inscrever((e) => {
      if (vivo) setEst(e);
    });
    return () => {
      vivo = false;
      sair();
    };
  }, []);
  return est;
}

function useUsoIA() {
  const [uso, setUso] = useState(0);
  useEffect(() => {
    let vivo = true;
    MassiIA.carregar().then(() => {
      if (vivo) setUso((n) => n + 1);
    });
    const sair = MassiIA.inscrever(() => {
      if (vivo) setUso((n) => n + 1);
    });
    return () => {
      vivo = false;
      sair();
    };
  }, []);
  return uso;
}
