function getVideoUrl(exercicio) {
  const porMaquina = VIDEOS_EXERCICIO[exercicio.name];
  if (!porMaquina) return null;
  // Só retorna vídeo se houver um cadastrado especificamente pra essa máquina.
  // (Removido o fallback pra "primeira opção cadastrada": ele mostrava vídeo
  // de equipamento errado quando a máquina escolhida não tinha vídeo próprio.
  // Agora, sem vídeo específico, cai na busca/canal do YouTube via getVideoOuCanalUrl.)
  return porMaquina[exercicio.maquina] || null;
}

// Capa (thumbnail) do vídeo cadastrado pro exercício/aparelho atual, extraída do próprio link do YouTube
function getThumbnailExercicio(exercicio) {
  const url = getVideoUrl(exercicio);
  if (!url) return null;
  const match = url.match(/(?:shorts\/|v=|youtu\.be\/)([a-zA-Z0-9_-]{6,})/);
  const id = match && match[1];
  if (!id) return null;
  return `https://img.youtube.com/vi/${id}/mqdefault.jpg`;
}

// Exercícios da categoria Funcional: quando não há vídeo específico cadastrado,
// a pessoa é direcionada aos vídeos do canal (em vez de uma busca genérica).
const NOMES_FUNCIONAL = new Set(LIBRARY.Funcional.map((e) => e.name));
const CANAL_FUNCIONAL_URL = "https://www.youtube.com/@Women-3D-Workouts/videos";

function getVideoOuCanalUrl(exercicio) {
  const videoEspecifico = getVideoUrl(exercicio);
  if (videoEspecifico) return { url: videoEspecifico, especifico: true };
  if (NOMES_FUNCIONAL.has(exercicio.name)) {
    return { url: CANAL_FUNCIONAL_URL, especifico: false, canal: true };
  }
  return {
    url: `https://www.youtube.com/results?search_query=${encodeURIComponent(exercicio.name + " execução correta")}`,
    especifico: false,
    canal: false,
  };
}

// ---------- Supervisor de vídeos: confere sozinho se todo exercício/máquina cadastrado
// na LIBRARY tem vídeo específico em VIDEOS_EXERCICIO. Roda automaticamente sempre que
// o app carrega — se alguém adicionar um exercício ou máquina nova sem vídeo, aparece
// aqui (e no console do navegador) em vez de descobrir só quando alguém reportar bug.
function auditarVideos() {
  const faltando = [];
  for (const grupo in LIBRARY) {
    for (const ex of LIBRARY[grupo]) {
      const videos = VIDEOS_EXERCICIO[ex.name];
      for (const maquina of ex.maquinas) {
        if (!videos || !videos[maquina]) {
          const usaCanal = NOMES_FUNCIONAL.has(ex.name);
          if (!faltando.some((f) => f.nome === ex.name && f.maquina === maquina)) {
            faltando.push({ grupo, nome: ex.name, maquina, usaCanal });
          }
        }
      }
    }
  }
  return faltando;
}
const AUDITORIA_VIDEOS = auditarVideos();
if (typeof console !== "undefined" && AUDITORIA_VIDEOS.some((f) => !f.usaCanal)) {
  console.warn(
    "[Massi Pro] Exercício/máquina sem vídeo específico cadastrado (cai na busca do YouTube):",
    AUDITORIA_VIDEOS.filter((f) => !f.usaCanal).map((f) => `${f.nome} → ${f.maquina}`)
  );
}

