function CalcAnilhasModal({ cargaInicial, onClose }) {
  const [cargaAlvo, setCargaAlvo] = useState(cargaInicial ? String(cargaInicial) : "");
  const [barra, setBarra] = useState(20);
  const { porLado, totalMontado, sobra } = calcularAnilhas(cargaAlvo, barra);

  return (
    <div style={styles.modalOverlay} onClick={onClose}>
      <div style={styles.modalCard} onClick={(e) => e.stopPropagation()}>
        <button style={styles.modalClose} onClick={onClose} aria-label={tr("Fechar")}>×</button>
        <h2 style={styles.modalTitle}>{tr("🏋️ Calculadora de anilhas")}</h2>
        <p style={styles.modalSubtitle}>
          {tr("Diz quanto você quer levantar no total (barra + anilhas) e a gente calcula quais anilhas colocar de cada lado da barra.")}</p>
        <div style={{ display: "flex", gap: 10, marginBottom: 14 }}>
          <div style={{ flex: 1 }}>
            <span style={styles.novoCampoLabel}>{tr("CARGA TOTAL (KG)")}</span>
            <input type="number" value={cargaAlvo} onChange={(e) => setCargaAlvo(e.target.value)} placeholder={tr("ex: 60")} style={styles.novoInputBox} />
          </div>
          <div style={{ flex: 1 }}>
            <span style={styles.novoCampoLabel}>{tr("PESO DA BARRA")}</span>
            <select value={barra} onChange={(e) => setBarra(Number(e.target.value))} style={styles.novoInputBox}>
              {BARRAS_PADRAO.map((b) => (
                <option key={b.nome} value={b.peso}>{tr(b.nome)}</option>
              ))}
            </select>
          </div>
        </div>
        {cargaAlvo && Number(cargaAlvo) > 0 ? (
          porLado.length > 0 ? (
            <div style={styles.cargaSeriesBox}>
              <div style={styles.cargaSeriesTitulo}>{tr("Anilhas de cada lado")}</div>
              <div style={{ fontFamily: monoFont, fontSize: 20, fontWeight: 700, color: INK, margin: "6px 0" }}>
                {tr(porLado.map((a) => `${a}kg`).join(" + "))}
              </div>
              <div style={{ fontSize: 12, opacity: 0.75 }}>
                {tr("Total montado: ")}{tr(totalMontado)}{tr("kg")}{sobra > 0 ? trt(" (sobra {0}kg que não dá pra bater exato com essas anilhas)", [sobra]) : tr("")}
              </div>
            </div>
          ) : (
            <div style={{ fontSize: 13, opacity: 0.7 }}>{tr("Essa carga é igual ou menor que o peso da barra — sem anilhas necessárias.")}</div>
          )
        ) : (
          <div style={{ fontSize: 13, opacity: 0.7 }}>{tr("Preencha a carga total pra ver as anilhas.")}</div>
        )}
      </div>
    </div>
  );
}

