function uid() {
  return Math.random().toString(36).slice(2, 9);
}

// Tenta salvar no window.storage algumas vezes antes de desistir de vez —
// cobre instabilidades momentâneas em vez de falhar na primeira tentativa.
async function salvarComRetentativa(chave, valor, tentativas = 3, esperaMs = 500) {
  for (let i = 0; i < tentativas; i++) {
    try {
      await window.storage.set(chave, valor);
      return true;
    } catch (e) {
      if (i < tentativas - 1) {
        await new Promise((resolve) => setTimeout(resolve, esperaMs));
      }
    }
  }
  return false;
}

function calcularStreak(historico) {
  if (!historico || historico.length === 0) return 0;
  const datasUnicas = [...new Set(historico.map((h) => h.data))].sort().reverse();
  const hoje = new Date().toISOString().slice(0, 10);
  const ontem = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
  if (datasUnicas[0] !== hoje && datasUnicas[0] !== ontem) return 0;
  let streak = 1;
  const semanasComFolgaUsada = new Set();
  for (let i = 0; i < datasUnicas.length - 1; i++) {
    const atual = new Date(datasUnicas[i]);
    const anterior = new Date(datasUnicas[i + 1]);
    const diffDias = Math.round((atual - anterior) / 86400000);
    if (diffDias === 1) {
      streak++;
    } else if (diffDias === 2) {
      // pulou exatamente 1 dia — permite 1 "congelamento" por semana sem quebrar a sequência
      const semanaDoGap = getChaveSemana(datasUnicas[i]);
      if (!semanasComFolgaUsada.has(semanaDoGap)) {
        semanasComFolgaUsada.add(semanaDoGap);
        streak++;
      } else {
        break;
      }
    } else {
      break;
    }
  }
  return streak;
}

function getChaveSemana(dataStr) {
  const d = new Date(dataStr + "T00:00:00");
  const inicioAno = new Date(d.getFullYear(), 0, 1);
  const numSemana = Math.ceil(((d - inicioAno) / 86400000 + inicioAno.getDay() + 1) / 7);
  return `${d.getFullYear()}-S${numSemana}`;
}

// conta quantas semanas seguidas (incluindo a atual) tiveram 3+ treinos, olhando pra trás
function calcularSemanasConsistentes(historico) {
  if (!historico || historico.length === 0) return 0;
  const porSemana = {};
  historico.forEach((h) => {
    const chave = getChaveSemana(h.data);
    porSemana[chave] = (porSemana[chave] || 0) + 1;
  });
  let streakSemanas = 0;
  let cursor = new Date();
  for (let i = 0; i < 20; i++) {
    const chave = getChaveSemana(cursor.toISOString().slice(0, 10));
    if ((porSemana[chave] || 0) >= 3) {
      streakSemanas++;
      cursor.setDate(cursor.getDate() - 7);
    } else {
      break;
    }
  }
  return streakSemanas;
}

// Assinatura da composição da rotina (quais exercícios em quais dias) — ignora
// séries/reps/carga de propósito, pra só contar como "trocou de treino" quando
// os exercícios em si mudam, não quando a pessoa só ajusta peso/série.
function assinaturaComposicaoRotina(rotina) {
  if (!rotina || !rotina.length) return "";
  const porDia = rotina
    .map((d) => ({ dia: d.dia, exs: (d.exercicios || []).map((e) => e.name).sort() }))
    .filter((d) => d.exs.length > 0)
    .sort((a, b) => a.dia.localeCompare(b.dia));
  return JSON.stringify(porDia);
}

function normalizarDecimal(valor) {
  return valor.replace(",", ".").replace(/[^0-9.]/g, "");
}

function calcularAguaLitros(pesoKg) {
  if (!pesoKg || pesoKg <= 0) return null;
  return +(pesoKg * 0.035).toFixed(1);
}

// Estimativa de % de gordura corporal pelo Método da Marinha dos EUA (por
// circunferências — não precisa de adipômetro). Homem: pescoço + cintura.
// Mulher: pescoço + cintura + quadril. Todas as medidas em cm.
// Retorna null se faltar algum dado necessário ou o resultado não fizer sentido.
function calcularPercentualGordura(sexo, alturaCm, pescocoCm, cinturaCm, quadrilCm) {
  const altura = Number(alturaCm);
  const pescoco = Number(pescocoCm);
  const cintura = Number(cinturaCm);
  const quadril = Number(quadrilCm);
  if (!altura || altura <= 0 || !pescoco || pescoco <= 0 || !cintura || cintura <= 0) return null;
  if (sexo === "feminino") {
    if (!quadril || quadril <= 0) return null;
    const diferenca = cintura + quadril - pescoco;
    if (diferenca <= 0) return null;
    const valor = 495 / (1.29579 - 0.35004 * Math.log10(diferenca) + 0.221 * Math.log10(altura)) - 450;
    return valor > 0 && valor < 70 ? +valor.toFixed(1) : null;
  }
  const diferenca = cintura - pescoco;
  if (diferenca <= 0) return null;
  const valor = 495 / (1.0324 - 0.19077 * Math.log10(diferenca) + 0.15456 * Math.log10(altura)) - 450;
  return valor > 0 && valor < 70 ? +valor.toFixed(1) : null;
}

// Faixas de referência aproximadas de % de gordura (American Council on Exercise),
// só pra dar contexto ao número — não é diagnóstico.
function faixaPercentualGordura(sexo, valor) {
  if (valor == null) return "";
  if (sexo === "feminino") {
    if (valor < 14) return "Atlético/essencial";
    if (valor < 21) return "Fitness";
    if (valor < 25) return "Aceitável";
    if (valor < 32) return "Acima da média";
    return "Alto";
  }
  if (valor < 6) return "Atlético/essencial";
  if (valor < 14) return "Fitness";
  if (valor < 18) return "Aceitável";
  if (valor < 25) return "Acima da média";
  return "Alto";
}

const KCAL_CARDIO_POR_MINUTO = { Leve: 6, Moderada: 8, Intensa: 11 };

function calcularCaloriasTreino(diaEntry) {
  let kcal = 0;
  diaEntry.exercicios.forEach((ex) => {
    const sets = ex.sets || 3;
    kcal += sets * 8; // estimativa média por série de musculação
  });
  if (diaEntry.cardio) {
    const porMinuto = KCAL_CARDIO_POR_MINUTO[diaEntry.cardio.intensidade] || 7;
    kcal += (diaEntry.cardio.duracao || 0) * porMinuto;
  }
  return Math.round(kcal);
}

function toExercicio(base) {
  return { id: uid(), ...base, maquina: escolherEquipamentoPadrao(base.maquinas), descanso: DESCANSO_PADRAO, concluido: false, carga: "", cargas: Array(base.sets || 1).fill(""), rirs: Array(base.sets || 1).fill(""), superset: false, dropset: false, personalizado: false };
}

const FRASES_MOTIVACIONAIS = [
  "Cada série te deixa mais perto do seu objetivo.",
  "Ninguém falou que seria fácil — só que ia valer a pena.",
  "Consistência vence intensidade. Continue voltando.",
  "O treino de hoje é o resultado de amanhã.",
  "Você já venceu a parte mais difícil: começar.",
  "Dor de hoje, força de amanhã.",
  "Progresso é progresso, não importa o tamanho.",
  "Foco no processo — o resultado é consequência.",
  "Respeita seu corpo, mas não subestima ele.",
  "Mais um treino, mais um passo.",
];

// Fórmula de Epley pra estimar carga máxima (1RM) a partir de uma carga e repetições feitas
function calcular1RM(cargaKg, reps) {
  const c = Number(cargaKg);
  const r = Number(reps);
  if (!c || !r || r <= 0) return null;
  if (r === 1) return Math.round(c);
  return Math.round(c * (1 + r / 30));
}

// Calculadora de anilhas: monta a combinação de anilhas (por lado) mais próxima do peso alvo,
// descontando o peso da barra
function calcularAnilhas(pesoAlvoKg, pesoBarraKg) {
  const alvo = Number(pesoAlvoKg);
  const barra = Number(pesoBarraKg) || 0;
  if (!alvo || alvo <= barra) return { porLado: [], totalPorLado: 0, totalMontado: barra, sobra: 0 };
  let restante = (alvo - barra) / 2;
  const porLado = [];
  for (const anilha of ANILHAS_DISPONIVEIS) {
    while (restante + 1e-9 >= anilha) {
      porLado.push(anilha);
      restante -= anilha;
    }
  }
  const totalPorLado = porLado.reduce((a, b) => a + b, 0);
  return { porLado, totalPorLado, totalMontado: barra + totalPorLado * 2, sobra: Math.round(restante * 100) / 100 };
}

function makeDayEntry(dia, foco, nivel) {
  const entry = makeDayEntryBase(dia, foco, nivel);
  // todo dia que não é descanso precisa de um período (Manhã/Tarde/Noite) pra notificação de treino
  return entry.foco === "Descanso" ? entry : { ...entry, periodo: entry.periodo || "Manhã" };
}

function makeDayEntryBase(dia, foco, nivel) {
  if (foco === "Cardio") {
    return { dia, foco, cardio: { tipo: "Esteira", duracao: 20, intensidade: "Moderada" }, exercicios: [] };
  }
  if (foco === "Descanso" || !foco) {
    return { dia, foco: foco || "Descanso", cardio: null, exercicios: [] };
  }

  const avancado = nivel === "Intermediário" || nivel === "Avançado";

  // ---- Regras de composição: agonista principal + sinergista + estabilizador ----
  if (foco === "Peito") {
    // agonista: 3 exercícios de peito cobrindo as 3 porções (inferior, medial, superior)
    const porRegiao = ["superior", "medial", "inferior"].map(
      (r) => LIBRARY.Peito.find((e) => e.regiao === r)
    ).filter(Boolean);
    const peitoEscolhido = porRegiao.length === 3 ? porRegiao : LIBRARY.Peito.slice(0, 3);
    // sinergista: sempre 3 de tríceps
    const tricepsEscolhido = TRICEPS_POOL.slice(0, 3);
    // estabilizador: 1 ou 2 de ombro, conforme o nível
    const ombroEscolhido = OMBRO_PRINCIPAL_POOL.slice(0, avancado ? 2 : 1);
    return {
      dia,
      foco,
      cardio: null,
      exercicios: [...peitoEscolhido, ...tricepsEscolhido, ...ombroEscolhido].map(toExercicio),
    };
  }

  if (foco === "Costas") {
    // agonista: 2 ou 3 de costas, conforme o nível
    const costasEscolhido = LIBRARY.Costas.slice(0, avancado ? 3 : 2);
    // sinergista: o complemento em bíceps (3 ou 2)
    const bicepsEscolhido = BICEPS_POOL.slice(0, avancado ? 2 : 3);
    // estabilizador: sempre 1 de deltoide posterior
    const posteriorEscolhido = OMBRO_POSTERIOR_POOL.slice(0, 1);
    return {
      dia,
      foco,
      cardio: null,
      exercicios: [...costasEscolhido, ...bicepsEscolhido, ...posteriorEscolhido].map(toExercicio),
    };
  }

  if (foco === "Ombro") {
    // "ombro sozinho completo": todas as porções (frontal, lateral, posterior)
    return {
      dia,
      foco,
      cardio: null,
      exercicios: LIBRARY.Ombro.map(toExercicio),
    };
  }

  if (foco === "Perna") {
    // "perna completa": quadríceps, posterior de coxa, glúteo e panturrilha
    return {
      dia,
      foco,
      cardio: null,
      exercicios: PERNA_COMPLETA_POOL.map(toExercicio),
    };
  }

  if (GER_FOCO_TIPO[foco] && foco !== "Corpo inteiro") {
    // foco criado pelo gerador, escolhido à mão em "Trocar foco do dia"
    const ctxAvulso = { obj: "hipertrofia", nivelIdx: ger_nivelIdx(nivel), duracao: 60, local: "academia", restricoes: [], prioridade: "equilibrado", seed: "avulso|" + foco, usados: {}, idxDia: 0 };
    const montado = ger_montarDia(GER_FOCO_TIPO[foco], ctxAvulso, 0);
    return { dia, foco, cardio: null, exercicios: montado.itens.map(ger_itemParaExercicio) };
  }
  const base = LIBRARY[foco] || [];
  return {
    dia,
    foco,
    cardio: null,
    exercicios: base.slice(0, 4).map(toExercicio),
  };
}

