  const [objetivoUsuario, setObjetivoUsuario] = useState(null); // objetivo do onboarding — usado pra pré-selecionar a dieta
  const [mostrarParabens, setMostrarParabens] = useState(false); // exibe o card de "Feliz aniversário" quando bate com a data de nascimento
  const [recordes, setRecordes] = useState({}); // recorde pessoal (maior carga já registrada) por exercício
  const [novoRecordeAviso, setNovoRecordeAviso] = useState(null); // texto do aviso de novo recorde, some sozinho
  const [avisoSaltoCarga, setAvisoSaltoCarga] = useState(null); // aviso de carga subindo rápido demais, some sozinho
  const [rirHistorico, setRirHistorico] = useState({}); // { "Supino reto": [{data, valor}, ...] } — últimos RIR registrados por exercício
  const [notasExercicio, setNotasExercicio] = useState({}); // { "Supino reto": "texto da anotação" }
  const [exercicioDesde, setExercicioDesde] = useState({}); // { "Segunda::Supino reto": "2026-01-01" } — desde quando esse exercício está nessa posição
  const [avisosExercicioParado, setAvisosExercicioParado] = useState({}); // { chave: "data do último aviso" } — evita repetir toda hora
  const [avisoExercicioParado, setAvisoExercicioParado] = useState(null); // toast atual, some sozinho
  const [avisoOvertreino, setAvisoOvertreino] = useState(null); // aviso de RIR 0 repetido, some sozinho
  const [avisoAumentarCarga, setAvisoAumentarCarga] = useState(null); // aviso de RIR sempre alto, some sozinho
  const [cargaHistorico, setCargaHistorico] = useState({}); // { "Supino reto": [{data, valor}, ...] }
  const [exerciciosFavoritos, setExerciciosFavoritos] = useState([]); // ["Supino reto", ...] — nomes marcados com estrela
  const [sugestaoTroca, setSugestaoTroca] = useState(null); // { dia, nomeAtual, nomeAlternativo } — sugestão após registrar dor
  const [deloadRespostaSemana, setDeloadRespostaSemana] = useState(null); // semana em que a pessoa já aplicou ou dispensou a sugestão de deload
  const [rotinaDataInicio, setRotinaDataInicio] = useState(null); // desde quando a composição atual da rotina (quais exercícios em quais dias) está em uso
  const [rotinaAssinaturaCarregada, setRotinaAssinaturaCarregada] = useState(undefined); // undefined = ainda carregando do storage; null = nunca salva antes
  const [trocaTreinoRespostaSemana, setTrocaTreinoRespostaSemana] = useState(null); // semana em que a pessoa já dispensou a sugestão de trocar de treino
  const [showPlanos, setShowPlanos] = useState(false);
  const [iaTela, setIaTela] = useState(null);
  const [pendenteIA, setPendenteIA] = useState(null); // tela de IA aguardando consentimento
  const [editandoQuestionario, setEditandoQuestionario] = useState(false);
  const [avisoPlanoIA, setAvisoPlanoIA] = useState(false);
  const [quick, setQuick] = useState({ sexo: null, obj: "hipertrofia", nivel: "Iniciante", dias: 4, local: "academia" });
  const montarPrimeiroTreino = () => {
    const params = { sexo: quick.sexo === "nd" ? null : quick.sexo, objetivo: quick.obj, nivel: quick.nivel, dias: quick.dias, duracao: 60, prioridade: "sugerida", local: quick.local, restricoes: [], variacao: 0 };
    try {
      const plano = gerarSemanaPersonalizada(params);
      aplicarPersonalizado(plano, params);
    } catch (e) {
      setErroPrimeiro(true);
    }
  };
  const [erroPrimeiro, setErroPrimeiro] = useState(false);
  const [dadosEdicao, setDadosEdicao] = useState(null);
  const abrirEdicaoQuestionario = async () => {
    let dados = {};
    try { const r = await window.storage.get("onboarding-perfil"); if (r && r.value) dados = JSON.parse(r.value) || {}; } catch (e) { dados = {}; }
    setDadosEdicao(dados);
    setShowPerfis(false);
    setEditandoQuestionario(true);
  };
  const abrirComConsentimento = async (tela) => {
    // A Rotina Inteligente já mostra a etiqueta Premium e as opções de plano na própria tela
    if (!vigente.temIA && tela !== "rotina") {
      setAvisoPlanoIA(true);
      return;
    }
    // Recursos de IA: só para maiores de 18 anos, com data de nascimento informada
    let nascimentoPerfil = null;
    try { const r = await window.storage.get("onboarding-perfil"); if (r && r.value) nascimentoPerfil = JSON.parse(r.value).nascimento; } catch (e) { nascimentoPerfil = null; }
    const idadePerfil = idadeDeNascimentoISO(nascimentoPerfil);
    if (idadePerfil === null || idadePerfil < 18) {
      setInfoModal({ titulo: "Recurso de IA indisponível", corpo: idadePerfil === null ? "Para usar os recursos de IA, informe sua data de nascimento no perfil." : "Os recursos de IA são destinados a maiores de 18 anos." });
      return;
    }
    let consentido = false;
    try { const r = await window.storage.get("consentimento-ia"); consentido = !!(r && r.value); } catch (e) { consentido = false; }
    if (consentido) setIaTela(tela); else setPendenteIA(tela);
  }; // telas de IA: "assistente" | "foto" | "diario" | "rotina" | null
  const [riVersao, setRiVersao] = useState(0); // sobe quando a Rotina Inteligente muda (atualiza o cartão da aba Rotina)
