    if (TOURS_ESSENCIAIS.indexOf(proximo) < 0 && TOURS_IA.indexOf(proximo) < 0) { setFilaTours((f) => f.slice(1)); return; }
    if (toursVistos[proximo] === true) { setFilaTours((f) => f.slice(1)); return; }
