    medir: anMedLado(["ombro", "cotovelo", "punho"], (l) => {
      const umero = anDist(l.ombro, l.cotovelo) || 1;
      return { valor: AN_ANG_COTOVELO(l), extras: { ombroAbaixo: (l.ombro.y - l.cotovelo.y) / umero } };
    }),
    regras: [anRegraFundo("ombroAbaixo", true, 0.45, "ombro", 20, "Não desça demais: o ombro bem abaixo do cotovelo sobrecarrega a articulação.")],
    vel: { min: 0.6, texto: "Desça controlado." },
