    medir: anMedLado(["ombro", "cotovelo", "punho", "quadril"], (l) => ({ valor: AN_ANG_COTOVELO(l), extras: { tronco: anInclinacao(l.quadril, l.ombro) } })),
    regras: [anRegraFundo("tronco", true, 35, "tronco", 20, "Não jogue o tronco muito para trás: incline só um pouco.")],
    vel: { min: 0.5, texto: "Puxe com controle, sem usar impulso." },
