function getWodDoDia() {
  const inicio = new Date(2026, 0, 1);
  const hoje = new Date();
  const diaDoAno = Math.max(0, Math.floor((hoje - inicio) / 86400000));
  const indice = diaDoAno % CROSS_WODS.length;
  return { ...CROSS_WODS[indice], numero: 100 + diaDoAno };
}

function formatarTempoCross(s) {
  const m = Math.floor(s / 60).toString().padStart(2, "0");
  const ss = Math.floor(s % 60).toString().padStart(2, "0");
  return `${m}:${ss}`;
}

// ---------- Tela de execução do WOD (cronômetro + rounds) ----------
function CrossExecucaoWod({ wod, onFinalizar, onCancelar }) {
  const [pausado, setPausado] = useState(false);
  const [segundos, setSegundos] = useState(0);
  const [roundsCompletos, setRoundsCompletos] = useState(0);
  const [finalizado, setFinalizado] = useState(false);

  useEffect(() => {
    if (pausado || finalizado) return undefined;
    const t = setInterval(() => setSegundos((s) => s + 1), 1000);
    return () => clearInterval(t);
  }, [pausado, finalizado]);

  const duracaoTotalSeg = (wod.duracaoMin || 10) * 60;
  const totalTabataSeg = Math.floor(duracaoTotalSeg / 30) * 30;

  useEffect(() => {
    if (finalizado) return;
    if ((wod.tipo === "amrap" || wod.tipo === "emom") && segundos >= duracaoTotalSeg) {
      setFinalizado(true);
      onFinalizar({ tempoSeg: duracaoTotalSeg, rounds: roundsCompletos });
    }
    if (wod.tipo === "tabata" && segundos >= totalTabataSeg) {
      setFinalizado(true);
      onFinalizar({ tempoSeg: totalTabataSeg, rounds: roundsCompletos });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [segundos, finalizado]);

  let painelFase = null;
  if (wod.tipo === "emom") {
    const minutoAtual = Math.min(Math.floor(segundos / 60) + 1, wod.duracaoMin);
    const restanteMin = 60 - (segundos % 60);
    const exercicioAtual = wod.exercicios[(minutoAtual - 1) % wod.exercicios.length];
    painelFase = (
      <div style={styles.crossFaseBox}>
        <div style={styles.crossFaseLabel}>{tr("Minuto ")}{tr(minutoAtual)} {tr("de ")}{tr(wod.duracaoMin)}</div>
        <div style={styles.crossExercicioAtual}>{tr(exercicioAtual.qtd)} {tr(exercicioAtual.exercicio)}</div>
        <div style={styles.crossFaseTempo}>{tr(restanteMin)}{tr("s restantes neste minuto")}</div>
        <CrossVideoBotao nome={exercicioAtual.exercicio} />
      </div>
    );
  } else if (wod.tipo === "tabata") {
    const cicloSeg = segundos % 30;
    const faseTrabalho = cicloSeg < 20;
    const cicloAtual = Math.min(Math.floor(segundos / 30) + 1, Math.floor(totalTabataSeg / 30));
    painelFase = (
      <div style={styles.crossFaseBox}>
        <div style={styles.crossFaseLabel}>{tr("Ciclo ")}{tr(cicloAtual)} {tr("de ")}{tr(Math.floor(totalTabataSeg / 30))}</div>
        <div style={{ ...styles.crossExercicioAtual, color: faseTrabalho ? HIGHLIGHT : MARGIN_RED }}>
          {faseTrabalho ? tr("🔥 TRABALHO") : tr("😮‍💨 DESCANSO")} — {tr(wod.exercicios[0].exercicio)}
        </div>
        <div style={styles.crossFaseTempo}>{faseTrabalho ? tr(20 - cicloSeg) : tr(30 - cicloSeg)}s</div>
        <CrossVideoBotao nome={wod.exercicios[0].exercicio} />
      </div>
    );
  } else {
    painelFase = (
      <div style={styles.crossFaseBox}>
        {wod.exercicios.map((ex, i) => (
          <div key={i} style={styles.crossExercicioLinha}>
            <div>• {tr(ex.qtd)} {tr(ex.exercicio)}</div>
            <CrossVideoBotao nome={ex.exercicio} />
          </div>
        ))}
      </div>
    );
  }

  const mostraRounds = wod.tipo === "rounds" || wod.tipo === "amrap";
  const contagemRegressiva = wod.tipo === "amrap" || wod.tipo === "emom" || wod.tipo === "tabata";
  const tempoExibido = contagemRegressiva
    ? formatarTempoCross(Math.max(0, (wod.tipo === "tabata" ? totalTabataSeg : duracaoTotalSeg) - segundos))
    : formatarTempoCross(segundos);

  return (
    <div>
      <div style={styles.crossExecucaoHeader}>
        <div style={styles.crossExecucaoWodNome}>{tr(wod.nome)}</div>
        <div style={styles.crossExecucaoTipo}>{tr(wod.tipo.toUpperCase())}</div>
      </div>
      <div style={styles.crossCronometroGrande}>{tr(tempoExibido)}</div>
      {tr(painelFase)}
      {mostraRounds && (
        <div style={styles.crossRoundsRow}>
          <button style={styles.crossRoundBtn} onClick={() => setRoundsCompletos((r) => Math.max(0, r - 1))}>−</button>
          <div style={styles.crossRoundsNumero}>{tr(roundsCompletos)} {tr("rounds")}</div>
          <button style={styles.crossRoundBtn} onClick={() => setRoundsCompletos((r) => r + 1)}>+</button>
        </div>
      )}
      <div style={styles.crossExecucaoBotoes}>
        <button style={styles.trocaManterBtn} onClick={() => setPausado((p) => !p)}>
          {pausado ? tr("▶ Retomar") : tr("⏸ Pausar")}
        </button>
        <button
          style={styles.saveButton}
          onClick={() => {
            if (finalizado) return;
            setFinalizado(true);
            onFinalizar({ tempoSeg: segundos, rounds: roundsCompletos });
          }}
        >
          {tr("✓ Finalizar")}</button>
      </div>
      <button style={styles.removerItemBtn} onClick={onCancelar}>{tr("Cancelar treino")}</button>
    </div>
  );
}

// ---------- Tela principal Massi Cross ----------
function MassiCrossTab({ refWodTour, refCategorias, refGerador, refAtalhos }) {
  const [tela, setTela] = useState("home");
  const [historico, setHistorico] = useState([]);
  const [recordes, setRecordes] = useState({});
  const [desafiosProgresso, setDesafiosProgresso] = useState({});
  const [wodAtivo, setWodAtivo] = useState(null);
  const [ultimoResultado, setUltimoResultado] = useState(null);
  const [exercicioAberto, setExercicioAberto] = useState(null);
  const [buscaExercicioCross, setBuscaExercicioCross] = useState("");
  const [inputDesafio, setInputDesafio] = useState({});

  const [genObjetivo, setGenObjetivo] = useState("Condicionamento");
  const [genNivel, setGenNivel] = useState("Intermediário");
  const [genDuracao, setGenDuracao] = useState(15);
  const [genEquipamento, setGenEquipamento] = useState("Sem equipamento");
  const [wodGerado, setWodGerado] = useState(null);
  const [categoriaAtual, setCategoriaAtual] = useState(null); // { titulo, lista } — usado pela grade de categorias

  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get("cross-historico");
        if (res && res.value) setHistorico(JSON.parse(res.value));
      } catch (e) {}
      try {
        const res = await window.storage.get("cross-recordes");
        if (res && res.value) setRecordes(JSON.parse(res.value));
      } catch (e) {}
      try {
        const res = await window.storage.get("cross-desafios-progresso");
        if (res && res.value) setDesafiosProgresso(JSON.parse(res.value));
      } catch (e) {}
    })();
  }, []);

  const wodDoDia = getWodDoDia();

  const atualizarDesafiosAutomaticos = async (hist) => {
    const streak = calcularStreak(hist);
    const totalWods = hist.length;
    setDesafiosProgresso((atual) => {
      const novo = { ...atual };
      CROSS_DESAFIOS.forEach((d) => {
        if (d.tipo === "dias-consecutivos") {
          novo[d.id] = { progresso: Math.min(streak, d.meta), concluido: streak >= d.meta };
        }
        if (d.tipo === "wods-completados") {
          novo[d.id] = { progresso: Math.min(totalWods, d.meta), concluido: totalWods >= d.meta };
        }
      });
      window.storage.set("cross-desafios-progresso", JSON.stringify(novo)).catch(() => {});
      return novo;
    });
  };

  const salvarResultado = async (wod, resultado) => {
    const registro = {
      id: uid(),
      data: new Date().toISOString().slice(0, 10),
      wodId: wod.id || wod.nome,
      wodNome: wod.nome,
      tipo: wod.tipo,
      tempoSeg: resultado.tempoSeg,
      rounds: resultado.rounds,
      nivel: wod.nivel,
    };
    const novoHistorico = [...historico, registro];
    setHistorico(novoHistorico);
    try {
      await window.storage.set("cross-historico", JSON.stringify(novoHistorico));
    } catch (e) {}

    const recAnterior = recordes[registro.wodId];
    let melhorou = false;
    let novoRecorde = recAnterior;
    if (!recAnterior) {
      melhorou = true;
      novoRecorde = { tempoSeg: registro.tempoSeg, rounds: registro.rounds, data: registro.data };
    } else if (wod.tipo === "fortime" || wod.tipo === "rounds") {
      if (registro.tempoSeg < recAnterior.tempoSeg) {
        melhorou = true;
        novoRecorde = { tempoSeg: registro.tempoSeg, rounds: registro.rounds, data: registro.data };
      }
    } else if (wod.tipo === "amrap" || wod.tipo === "tabata") {
      if (registro.rounds > recAnterior.rounds) {
        melhorou = true;
        novoRecorde = { tempoSeg: registro.tempoSeg, rounds: registro.rounds, data: registro.data };
      }
    }
    if (melhorou) {
      const novosRecordes = { ...recordes, [registro.wodId]: novoRecorde };
      setRecordes(novosRecordes);
      try {
        await window.storage.set("cross-recordes", JSON.stringify(novosRecordes));
      } catch (e) {}
    }

    atualizarDesafiosAutomaticos(novoHistorico);

    setUltimoResultado({ registro, anterior: recAnterior, melhorou });
    setWodAtivo(null);
    setTela("resultado");
  };

  const registrarProgressoManual = async (desafio) => {
    const valor = parseFloat((inputDesafio[desafio.id] || "").toString().replace(",", "."));
    if (!valor || valor <= 0) return;
    const atual = desafiosProgresso[desafio.id] || { progresso: 0, concluido: false };
    const novoValor = Math.min(atual.progresso + valor, desafio.meta);
    const novoProgresso = {
      ...desafiosProgresso,
      [desafio.id]: { progresso: novoValor, concluido: novoValor >= desafio.meta },
    };
    setDesafiosProgresso(novoProgresso);
    setInputDesafio((prev) => ({ ...prev, [desafio.id]: "" }));
    try {
      await window.storage.set("cross-desafios-progresso", JSON.stringify(novoProgresso));
    } catch (e) {}
  };

  const gerarWod = () => {
    const candidatos = CROSS_WODS.filter(
      (w) =>
        w.nivel === genNivel &&
        Math.abs(w.duracaoMin - genDuracao) <= 10 &&
        (genEquipamento === "Academia completa" || w.equipamento === genEquipamento || w.equipamento === "Sem equipamento")
    );
    const pool = candidatos.length > 0 ? candidatos : CROSS_WODS.filter((w) => w.nivel === genNivel);
    const escolhido = pool.length > 0 ? pool[Math.floor(Math.random() * pool.length)] : CROSS_WODS[0];
    setWodGerado({ ...escolhido, duracaoMin: genDuracao, objetivoGerado: genObjetivo });
  };

  const totalWodsConcluidos = historico.length;
  const tempoTotalTreinoSeg = historico.reduce((acc, h) => acc + (h.tempoSeg || 0), 0);
  const streakCross = calcularStreak(historico);
  const temposValidos = historico.filter((h) => h.tempoSeg).map((h) => h.tempoSeg);
  const melhorTempoGeral = temposValidos.length > 0 ? Math.min(...temposValidos) : null;
  const desafiosConcluidos = Object.values(desafiosProgresso).filter((d) => d.concluido).length;
  const dadosEvolucao = historico.slice(-10).map((h, i) => ({ treino: i + 1, minutos: Math.round(((h.tempoSeg || 0) / 60) * 10) / 10 }));

  const exercFiltrados = CROSS_EXERCICIOS.filter((e) =>
    e.nome.toLowerCase().includes(buscaExercicioCross.trim().toLowerCase())
  );

  const voltar = () => setTela("home");

  // ---------- WOD ativo (execução) ----------
  if (wodAtivo) {
    return (
      <CrossExecucaoWod
        wod={wodAtivo}
        onCancelar={() => setWodAtivo(null)}
        onFinalizar={(resultado) => salvarResultado(wodAtivo, resultado)}
      />
    );
  }

  // ---------- Resultado ----------
  if (tela === "resultado" && ultimoResultado) {
    const { registro, anterior, melhorou } = ultimoResultado;
    let comparacao = null;
    if (anterior) {
      if (registro.tipo === "fortime" || registro.tipo === "rounds") {
        const diff = anterior.tempoSeg - registro.tempoSeg;
        const pct = anterior.tempoSeg > 0 ? Math.round((diff / anterior.tempoSeg) * 100) : 0;
        comparacao = diff > 0
          ? `⚡ Você foi ${pct}% mais rápido que seu último resultado!`
          : diff < 0
          ? `Seu último tempo foi ${formatarTempoCross(anterior.tempoSeg)} — continue treinando!`
          : "Você repetiu exatamente o seu último tempo!";
      } else if (registro.tipo === "amrap" || registro.tipo === "tabata") {
        const diff = registro.rounds - anterior.rounds;
        comparacao = diff > 0
          ? `⚡ Você fez ${diff} round(s) a mais que da última vez!`
          : diff < 0
          ? `Da última vez você fez ${anterior.rounds} rounds — continue treinando!`
          : "Você repetiu exatamente o resultado anterior!";
      }
    }
    return (
      <div>
        <div style={styles.crossResultadoEmoji}>{tr("🏆 WOD CONCLUÍDO!")}</div>
        <div style={styles.crossResultadoTempo}>{tr(formatarTempoCross(registro.tempoSeg))}</div>
        {(registro.tipo === "rounds" || registro.tipo === "amrap" || registro.tipo === "tabata") && (
          <div style={styles.crossResultadoDetalhe}>{tr(registro.rounds)} {tr("ROUNDS")}</div>
        )}
        <div style={styles.crossResultadoDetalhe}>{tr(registro.wodNome)}</div>
        {melhorou && !comparacao && (
          <div style={styles.crossResultadoComparacao}>{tr("🏅 Novo recorde pessoal nesse WOD!")}</div>
        )}
        {comparacao && <div style={styles.crossResultadoComparacao}>{tr(comparacao)}</div>}
        <button style={styles.saveButton} onClick={voltar}>{tr("Voltar pra Massi Cross")}</button>
      </div>
    );
  }

  // ---------- Biblioteca de exercícios ----------
  if (tela === "biblioteca") {
    if (exercicioAberto) {
      return (
        <div>
          <button style={styles.crossVoltarBtn} onClick={() => setExercicioAberto(null)}>{tr("← Voltar")}</button>
          <section style={styles.card}>
            <div style={styles.cardLabel}>{tr(exercicioAberto.nome)}</div>
            <CrossVideoBotao nome={exercicioAberto.nome} />
            <div style={styles.crossExercicioDetalheLabel}>{tr("Como executar")}</div>
            <div style={styles.crossExercicioDetalheValor}>{tr(exercicioAberto.comoExecutar)}</div>
            <div style={styles.crossExercicioDetalheLabel}>{tr("Nível de dificuldade")}</div>
            <div style={styles.crossExercicioDetalheValor}>{tr(exercicioAberto.nivel)}</div>
            <div style={styles.crossExercicioDetalheLabel}>{tr("Equipamento necessário")}</div>
            <div style={styles.crossExercicioDetalheValor}>{tr(exercicioAberto.equipamento)}</div>
            <div style={styles.crossExercicioDetalheLabel}>{tr("Músculos/regiões trabalhadas")}</div>
            <div style={styles.crossExercicioDetalheValor}>{tr(exercicioAberto.musculos)}</div>
          </section>
        </div>
      );
    }
    return (
      <div>
        <button style={styles.crossVoltarBtn} onClick={voltar}>{tr("← Voltar")}</button>
        <input
          type="text"
          value={buscaExercicioCross}
          onChange={(e) => setBuscaExercicioCross(e.target.value)}
          placeholder={tr("🔎 Buscar exercício…")}
          style={styles.buscaInput}
        />
        <div style={styles.crossListaExercicios}>
          {exercFiltrados.map((ex) => (
            <button key={ex.id} style={styles.crossExercicioCard} onClick={() => setExercicioAberto(ex)}>
              <div style={styles.crossExercicioNome}>{tr(ex.nome)}</div>
              <div style={styles.crossExercicioMeta}>{tr(ex.nivel)} • {tr(ex.equipamento)}</div>
            </button>
          ))}
        </div>
      </div>
    );
  }

  // ---------- Gerador de WOD ----------
  if (tela === "gerador") {
    return (
      <div>
        <button style={styles.crossVoltarBtn} onClick={voltar}>{tr("← Voltar")}</button>
        <section style={styles.card}>
          <div style={styles.cardLabel}>{tr("Gerar meu WOD")}</div>
          <div style={styles.crossGeradorForm}>
            <label style={styles.crossGeradorLabel}>
              {tr("Objetivo")}<select style={styles.crossGeradorSelect} value={genObjetivo} onChange={(e) => setGenObjetivo(e.target.value)}>
                {["Condicionamento", "Emagrecimento", "Resistência", "Força"].map((o) => (
                  <option key={o} value={o}>{tr(o)}</option>
                ))}
              </select>
            </label>
            <label style={styles.crossGeradorLabel}>
              {tr("Nível")}<select style={styles.crossGeradorSelect} value={genNivel} onChange={(e) => setGenNivel(e.target.value)}>
                {["Iniciante", "Intermediário", "Avançado"].map((n) => (
                  <option key={n} value={n}>{tr(n)}</option>
                ))}
              </select>
            </label>
            <label style={styles.crossGeradorLabel}>
              {tr("Duração")}<select style={styles.crossGeradorSelect} value={genDuracao} onChange={(e) => setGenDuracao(Number(e.target.value))}>
                {[10, 15, 20, 30, 45].map((d) => (
                  <option key={d} value={d}>{tr(d)} {tr("min")}</option>
                ))}
              </select>
            </label>
            <label style={styles.crossGeradorLabel}>
              {tr("Equipamento")}<select style={styles.crossGeradorSelect} value={genEquipamento} onChange={(e) => setGenEquipamento(e.target.value)}>
                {["Sem equipamento", "Equipamentos básicos", "Academia completa"].map((eq) => (
                  <option key={eq} value={eq}>{tr(eq)}</option>
                ))}
              </select>
            </label>
          </div>
          <button style={styles.saveButton} onClick={gerarWod}>{tr("Gerar meu WOD")}</button>
        </section>

        {wodGerado && (
          <section style={styles.crossWodDestaqueCard}>
            <div style={styles.crossWodDestaqueLabel}>{tr("SEU WOD — ")}{tr(wodGerado.nome)}</div>
            <div style={styles.crossWodDestaqueMeta}>{tr(wodGerado.duracaoMin)} {tr("minutos • ")}{tr(wodGerado.nivel)} • {tr(wodGerado.tipo.toUpperCase())}</div>
            <div style={styles.crossWodDestaqueLista}>
              {wodGerado.exercicios.map((ex, i) => (
                <div key={i} style={styles.crossWodDestaqueItem}>• {tr(ex.qtd)} {tr(ex.exercicio)}</div>
              ))}
            </div>
            <button style={styles.crossBtnComecar} onClick={() => setWodAtivo(wodGerado)}>{tr("COMEÇAR WOD")}</button>
          </section>
        )}
      </div>
    );
  }

  // ---------- Categoria (grade nova: Força, Metcon, EMOM, AMRAP, For Time, Benchmark, Sem/Com equipamento) ----------
  if (tela === "categoria" && categoriaAtual) {
    return (
      <div>
        <button style={styles.crossVoltarBtn} onClick={voltar}>{tr("← Voltar")}</button>
        <div style={styles.crossSecaoTitulo}>{tr(categoriaAtual.titulo)}</div>
        {categoriaAtual.lista.length === 0 ? (
          <div style={styles.restNote}>{tr("Nenhum WOD nessa categoria ainda.")}</div>
        ) : (
          <div style={styles.crossListaExercicios}>
            {categoriaAtual.lista.map((w) => (
              <button key={w.id} style={styles.crossExercicioCard} onClick={() => setWodAtivo(w)}>
                <div style={styles.crossExercicioNome}>{w.famoso ? tr(`🏆 ${w.nome}`) : tr(w.nome)}</div>
                <div style={styles.crossExercicioMeta}>{tr(w.duracaoMin)} {tr("min • ")}{tr(w.nivel)} • {tr(w.tipo.toUpperCase())} • {tr(w.equipamento)}</div>
              </button>
            ))}
          </div>
        )}
      </div>
    );
  }

  // ---------- Treinos rápidos ----------
  if (tela === "rapidos") {
    return (
      <div>
        <button style={styles.crossVoltarBtn} onClick={voltar}>{tr("← Voltar")}</button>
        <div style={styles.crossListaExercicios}>
          {[10, 15, 20, 30].map((min) => {
            const opcoes = CROSS_WODS.filter((w) => w.duracaoMin === min);
            return opcoes.map((w) => (
              <button key={w.id} style={styles.crossExercicioCard} onClick={() => setWodAtivo(w)}>
                <div style={styles.crossExercicioNome}>{tr(w.nome)}</div>
                <div style={styles.crossExercicioMeta}>{tr(w.duracaoMin)} {tr("min • ")}{tr(w.nivel)} • {tr(w.tipo.toUpperCase())}</div>
              </button>
            ));
          })}
        </div>
      </div>
    );
  }

  // ---------- Desafios ----------
  if (tela === "desafios") {
    return (
      <div>
        <button style={styles.crossVoltarBtn} onClick={voltar}>{tr("← Voltar")}</button>
        {CROSS_DESAFIOS.map((d) => {
          const prog = desafiosProgresso[d.id] || { progresso: 0, concluido: false };
          const pct = Math.min(100, Math.round((prog.progresso / d.meta) * 100));
          const manual = d.tipo === "contagem" || d.tipo === "distancia-km";
          return (
            <section key={d.id} style={styles.crossDesafioCard}>
              <div style={styles.crossDesafioNome}>{tr(d.emoji)} {tr(d.nome)} {prog.concluido && <span style={styles.crossDesafioBadge}>{tr("CONCLUÍDO")}</span>}</div>
              <div style={styles.crossDesafioDescricao}>{tr(d.descricao)}</div>
              <div style={styles.crossDesafioBarraFundo}>
                <div style={{ ...styles.crossDesafioBarraPreenchida, width: `${pct}%` }} />
              </div>
              <div style={styles.crossDesafioProgressoTexto}>
                {tr(Math.round(prog.progresso * 10) / 10)} / {tr(d.meta)} {tr(d.unidade)} ({tr(pct)}%)
              </div>
              {manual && !prog.concluido && (
                <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
                  <input
                    type="number"
                    value={inputDesafio[d.id] || ""}
                    onChange={(e) => setInputDesafio((prev) => ({ ...prev, [d.id]: e.target.value }))}
                    placeholder={tr(`+ ${d.unidade}`)}
                    style={styles.avalInput}
                  />
                  <button style={styles.trocaManterBtn} onClick={() => registrarProgressoManual(d)}>{tr("Registrar")}</button>
                </div>
              )}
            </section>
          );
        })}
      </div>
    );
  }

  // ---------- Desempenho ----------
  if (tela === "desempenho") {
    return (
      <div>
        <button style={styles.crossVoltarBtn} onClick={voltar}>{tr("← Voltar")}</button>
        <div style={styles.crossDesempenhoGrid}>
          <div style={styles.crossDesempenhoItem}>
            <div style={styles.crossDesempenhoNumero}>{tr(totalWodsConcluidos)}</div>
            <div style={styles.crossDesempenhoLabel}>{tr("WODs concluídos")}</div>
          </div>
          <div style={styles.crossDesempenhoItem}>
            <div style={styles.crossDesempenhoNumero}>{tr(formatarTempoCross(tempoTotalTreinoSeg))}</div>
            <div style={styles.crossDesempenhoLabel}>{tr("tempo total treinando")}</div>
          </div>
          <div style={styles.crossDesempenhoItem}>
            <div style={styles.crossDesempenhoNumero}>{tr(streakCross)}🔥</div>
            <div style={styles.crossDesempenhoLabel}>{tr("dias seguidos")}</div>
          </div>
          <div style={styles.crossDesempenhoItem}>
            <div style={styles.crossDesempenhoNumero}>{melhorTempoGeral !== null ? tr(formatarTempoCross(melhorTempoGeral)) : tr("—")}</div>
            <div style={styles.crossDesempenhoLabel}>{tr("melhor tempo")}</div>
          </div>
          <div style={styles.crossDesempenhoItem}>
            <div style={styles.crossDesempenhoNumero}>{tr(desafiosConcluidos)}</div>
            <div style={styles.crossDesempenhoLabel}>{tr("desafios concluídos")}</div>
          </div>
        </div>

        {dadosEvolucao.length > 1 && (
          <section style={styles.card}>
            <div style={styles.cardLabel}>{tr("Evolução (últimos treinos)")}</div>
            <ResponsiveContainer width="100%" height={180}>
              <LineChart data={dadosEvolucao}>
                <CartesianGrid strokeDasharray="3 3" opacity={0.15} />
                <XAxis dataKey="treino" fontSize={11} />
                <YAxis fontSize={11} />
                <Tooltip />
                <Line type="monotone" dataKey="minutos" stroke={MARGIN_RED} strokeWidth={2} dot={{ r: 3 }} />
              </LineChart>
            </ResponsiveContainer>
          </section>
        )}

        {Object.keys(recordes).length > 0 && (
          <section style={styles.card}>
            <div style={styles.cardLabel}>{tr("Recordes pessoais")}</div>
            {Object.entries(recordes).map(([wodId, r]) => {
              const wodInfo = CROSS_WODS.find((w) => w.id === wodId) || { nome: wodId };
              return (
                <div key={wodId} style={styles.historicoLinha}>
                  <span>{tr(wodInfo.nome)}</span>
                  <span>{tr(formatarTempoCross(r.tempoSeg))}{r.rounds ? trt(" • {0} rounds", [r.rounds]) : tr("")}</span>
                </div>
              );
            })}
          </section>
        )}

        <section style={styles.card}>
          <div style={styles.cardLabel}>{tr("Consistência")}</div>
          <ConsistenciaHeatmap historico={historico} />
        </section>
      </div>
    );
  }

  // ---------- Home ----------
  return (
    <div style={styles.crossDarkWrap}>
      <div style={styles.crossHeroDark}>
        <div style={styles.crossHeroTituloDark}>{tr("Massi ")}<span style={{ color: CROSS_LIME }}>{tr("Cross")}</span></div>
        <div style={styles.crossHeroSubtituloDark}>{tr("Supere seus limites. Registre sua evolução.")}</div>
      </div>

      <section style={styles.crossWodDestaqueCard}>
        <div style={styles.crossWodDestaqueLabel}>{tr("🔥 WOD DO DIA")}</div>
        <div style={styles.crossWodDestaqueNumero}>{tr("WOD #")}{tr(wodDoDia.numero)} — {tr(wodDoDia.nome)}</div>
        <div style={styles.crossWodDestaqueMeta}>{tr(wodDoDia.duracaoMin)} {tr("minutos • ")}{tr(wodDoDia.nivel)} • {tr(wodDoDia.tipo.toUpperCase())}</div>
        <div style={styles.crossWodDestaqueLista}>
          {wodDoDia.tipo === "rounds" && <div style={styles.crossWodDestaqueItem}>{tr(wodDoDia.rounds)} {tr("ROUNDS:")}</div>}
          {wodDoDia.exercicios.map((ex, i) => (
            <div key={i} style={styles.crossWodDestaqueItem}>• {tr(ex.qtd)} {tr(ex.exercicio)}</div>
          ))}
        </div>
        <button style={styles.crossBtnComecar} onClick={() => setWodAtivo(wodDoDia)} ref={refWodTour}>{tr("COMEÇAR WOD")}</button>
      </section>

      <div style={styles.crossCategoriasGridDark} ref={refCategorias}>
        {CROSS_CATEGORIAS_GRID.map((cat) => (
          <button
            key={cat.chave}
            style={styles.crossCategoriaCardDark}
            onClick={() => {
              setCategoriaAtual({ titulo: cat.label, lista: CROSS_WODS.filter(cat.filtro) });
              setTela("categoria");
            }}
          >
            <div style={styles.crossCategoriaEmojiDark}>{tr(cat.emoji)}</div>
            <div style={styles.crossCategoriaLabelDark}>{tr(cat.label)}</div>
            <div style={styles.crossCategoriaSubDark}>{tr(cat.sub)}</div>
          </button>
        ))}
      </div>

      <div style={styles.crossAtalhosRow} ref={refAtalhos}>
        <button style={styles.crossAtalhoBtn} onClick={() => setTela("gerador")} ref={refGerador}>{tr("🧠 Gerar meu WOD")}</button>
        <button style={styles.crossAtalhoBtn} onClick={() => setTela("biblioteca")}>{tr("📚 Biblioteca")}</button>
        <button style={styles.crossAtalhoBtn} onClick={() => setTela("desafios")}>{tr("🏆 Desafios")}</button>
        <button style={styles.crossAtalhoBtn} onClick={() => setTela("desempenho")}>{tr("📊 Desempenho")}</button>
      </div>
    </div>
  );
}



function getUltimaDorRelacionada(nomeExercicio, dores) {
  if (!dores || dores.length === 0) return null;
  // Prioridade 1: dor registrada nesse exercício exato
  const mesmoExercicio = [...dores]
    .filter((d) => d.exercicio === nomeExercicio)
    .sort((a, b) => (a.data < b.data ? 1 : -1))[0];
  if (mesmoExercicio) return { ...mesmoExercicio, mesmoGrupo: false };

  // Prioridade 2: dor registrada em outro exercício do mesmo grupo muscular
  const grupoAtual = GUIA_EXECUCAO[nomeExercicio] && GUIA_EXECUCAO[nomeExercicio].grupoMuscular;
  if (!grupoAtual) return null;
  const gruposAtuais = grupoAtual.split(",").map((g) => g.trim().toLowerCase());

  const mesmoGrupo = [...dores]
    .filter((d) => {
      if (d.exercicio === nomeExercicio) return false;
      const grupoOutro = GUIA_EXECUCAO[d.exercicio] && GUIA_EXECUCAO[d.exercicio].grupoMuscular;
      if (!grupoOutro) return false;
      const gruposOutro = grupoOutro.split(",").map((g) => g.trim().toLowerCase());
      return gruposAtuais.some((g) => gruposOutro.includes(g));
    })
    .sort((a, b) => (a.data < b.data ? 1 : -1))[0];
  return mesmoGrupo ? { ...mesmoGrupo, mesmoGrupo: true } : null;
}

// Acha o contêiner que rola (a página inteira ou uma área interna).
function tourAcharRolavel(el) {
  let pai = el.parentElement;
  while (pai && pai !== document.body && pai !== document.documentElement) {
    const cs = window.getComputedStyle(pai);
    if (/(auto|scroll)/.test(cs.overflowY) && pai.scrollHeight > pai.clientHeight + 4) return pai;
    pai = pai.parentElement;
  }
  return null;
}
// Rola a tela (sem animação, para funcionar em qualquer celular) até o item do tutorial aparecer.
function tourRolarAte(el, soSeFora) {
  const r = el.getBoundingClientRect();
  const alto = window.innerHeight;
  const grande = r.height > alto * 0.55;
  if (soSeFora && r.top >= 60 && r.bottom <= alto - 20) return;
  const desejado = grande ? 70 : Math.max(70, alto * 0.36 - r.height / 2);
  const delta = r.top - desejado;
  if (Math.abs(delta) < 4) return;
  const rolavel = tourAcharRolavel(el);
  if (rolavel) rolavel.scrollTo({ top: rolavel.scrollTop + delta, behavior: "auto" });
  else window.scrollTo({ top: (window.pageYOffset || document.documentElement.scrollTop || 0) + delta, behavior: "auto" });
}

// Botão flutuante do Assistente Massi: dá pra arrastar pra qualquer lugar da
// tela (dedo ou mouse). A posição fica salva no aparelho. Toque curto abre o
// assistente; arrastar só move. Usa só toque/mouse e position:fixed (nada de
// recurso de CSS que o WebView ignora).
const IA_BTN_TAM = 54;
const IA_BTN_MARGEM = 6;
let IA_BTN_POS_CACHE = null; // evita o botão "pular" ao reabrir depois de um modal
function BotaoIAFlutuante({ onAbrir, rotulo, btnRef }) {
  const elRef = useRef(null);
  const [pos, setPos] = useState(IA_BTN_POS_CACHE); // { x, y } em px, ou null = canto padrão
  const [arrastando, setArrastando] = useState(false);
  const posRef = useRef(IA_BTN_POS_CACHE);
  const dragRef = useRef({ ativo: false, moveu: false, offX: 0, offY: 0, startX: 0, startY: 0 });

  const limitar = (x, y) => {
    const maxX = Math.max(IA_BTN_MARGEM, window.innerWidth - IA_BTN_TAM - IA_BTN_MARGEM);
    const maxY = Math.max(IA_BTN_MARGEM, window.innerHeight - IA_BTN_TAM - IA_BTN_MARGEM);
    return {
      x: Math.min(Math.max(IA_BTN_MARGEM, x), maxX),
      y: Math.min(Math.max(IA_BTN_MARGEM, y), maxY),
    };
  };

  // Carrega a posição salva (só se ainda não estiver no cache).
  useEffect(() => {
    if (IA_BTN_POS_CACHE) return;
    let cancelado = false;
    (async () => {
      try {
        const r = await window.storage.get("ia-botao-pos");
        if (r && r.value && !cancelado) {
          const p = JSON.parse(r.value);
          if (p && typeof p.x === "number" && typeof p.y === "number") {
            const l = limitar(p.x, p.y);
            IA_BTN_POS_CACHE = l;
            posRef.current = l;
            setPos(l);
          }
        }
      } catch (e) {
        // sem posição salva: fica no canto padrão
      }
    })();
    return () => { cancelado = true; };
  }, []);

  // Se a tela girar/redimensionar, mantém o botão dentro da tela.
  useEffect(() => {
    const aoRedimensionar = () => {
      if (!posRef.current) return;
      const l = limitar(posRef.current.x, posRef.current.y);
      posRef.current = l;
      IA_BTN_POS_CACHE = l;
      setPos(l);
    };
    window.addEventListener("resize", aoRedimensionar);
    return () => window.removeEventListener("resize", aoRedimensionar);
  }, []);

  // Arrastar (toque e mouse). Os listeners são nativos pra poder cancelar a
  // rolagem da página enquanto o botão está sendo arrastado.
  useEffect(() => {
    const el = elRef.current;
    if (!el) return;
    const iniciar = (cx, cy) => {
      const r = el.getBoundingClientRect();
      dragRef.current = { ativo: true, moveu: false, offX: cx - r.left, offY: cy - r.top, startX: cx, startY: cy };
    };
    const mover = (cx, cy) => {
      const d = dragRef.current;
      if (!d.ativo) return false;
      if (!d.moveu) {
        if (Math.abs(cx - d.startX) < 6 && Math.abs(cy - d.startY) < 6) return false;
        d.moveu = true;
        setArrastando(true);
      }
      const l = limitar(cx - d.offX, cy - d.offY);
      posRef.current = l;
      setPos(l);
      return true;
    };
    const terminar = () => {
      const d = dragRef.current;
      if (!d.ativo) return false;
      d.ativo = false;
      if (!d.moveu) return false;
      setArrastando(false);
      if (posRef.current) {
        IA_BTN_POS_CACHE = posRef.current;
        try {
          const p = window.storage.set("ia-botao-pos", JSON.stringify(posRef.current));
          if (p && p.catch) p.catch(() => {});
        } catch (e) {
          // posição só não fica salva; segue normal
        }
      }
      return true;
    };
    const tStart = (e) => {
      if (!e.touches || e.touches.length !== 1) return;
      iniciar(e.touches[0].clientX, e.touches[0].clientY);
    };
    const tMove = (e) => {
      if (!dragRef.current.ativo || !e.touches || e.touches.length < 1) return;
      if (mover(e.touches[0].clientX, e.touches[0].clientY) && e.cancelable) e.preventDefault();
    };
    const tEnd = (e) => {
      if (terminar() && e.cancelable) e.preventDefault(); // evita o "clique" depois de arrastar
    };
    const mDown = (e) => {
      if (e.button !== undefined && e.button !== 0) return;
      iniciar(e.clientX, e.clientY);
    };
    const mMove = (e) => {
      if (dragRef.current.ativo) mover(e.clientX, e.clientY);
    };
    const mUp = () => { terminar(); };
    el.addEventListener("touchstart", tStart, { passive: true });
    el.addEventListener("touchmove", tMove, { passive: false });
    el.addEventListener("touchend", tEnd, { passive: false });
    el.addEventListener("touchcancel", tEnd, { passive: false });
    el.addEventListener("mousedown", mDown);
    window.addEventListener("mousemove", mMove);
    window.addEventListener("mouseup", mUp);
    return () => {
      el.removeEventListener("touchstart", tStart);
      el.removeEventListener("touchmove", tMove);
      el.removeEventListener("touchend", tEnd);
      el.removeEventListener("touchcancel", tEnd);
      el.removeEventListener("mousedown", mDown);
      window.removeEventListener("mousemove", mMove);
      window.removeEventListener("mouseup", mUp);
    };
  }, []);

  const aoClicar = () => {
    if (dragRef.current.moveu) {
      dragRef.current.moveu = false; // clique que sobrou de um arraste: ignora
      return;
    }
    onAbrir();
  };

  const posEstilo = pos
    ? { left: pos.x, top: pos.y }
    : { right: 16, bottom: "calc(18px + env(safe-area-inset-bottom, 0px))" };

  return (
    <button
      ref={(el) => { elRef.current = el; if (btnRef) btnRef.current = el; }}
      onClick={aoClicar}
      aria-label={rotulo}
      title={rotulo}
      style={{
        position: "fixed",
        ...posEstilo,
        zIndex: 400,
        width: IA_BTN_TAM,
        height: IA_BTN_TAM,
        padding: 0,
        borderRadius: "50%",
        border: "none",
        background: "linear-gradient(135deg, #B7E04A, #7FAE1F)",
        color: "#10150A",
        fontSize: 24,
        cursor: arrastando ? "grabbing" : "grab",
        boxShadow: arrastando ? "0 10px 26px rgba(0,0,0,0.6)" : "0 6px 18px rgba(0,0,0,0.45)",
        transform: arrastando ? "scale(1.08)" : "none",
        touchAction: "none",
        userSelect: "none",
        WebkitUserSelect: "none",
        WebkitTapHighlightColor: "transparent",
      }}
    >
      ✨
    </button>
  );
}

function TourOverlay({ alvoRef, texto, onProximo, onPular, onPularTudo, ultimo }) {
  const [rect, setRect] = useState(null);
  const [semAlvo, setSemAlvo] = useState(false);
  const [pronto, setPronto] = useState(false); // balão só aparece depois que a tela terminou de rolar
  const balaoRef = useRef(null);

  useEffect(() => {
    let cancelado = false;
    let intervalId = null;
    const timers = [];
    setRect(null);
    setSemAlvo(false);
    setPronto(false);
    function medir() {
      if (cancelado || !alvoRef || !alvoRef.current) return;
      setRect(alvoRef.current.getBoundingClientRect());
    }
    const el = alvoRef && alvoRef.current;
    if (el) {
      // 1) leva o item para a tela; 2) confere de novo depois que a página se ajusta
      tourRolarAte(el, false);
      timers.push(setTimeout(medir, 60));
      // Só mostra o balão depois que a página para de rolar (ou no máximo após 1,5 s)
      let idleId = null;
      const aoRolar = () => { medir(); clearTimeout(idleId); idleId = setTimeout(() => setPronto(true), 250); };
      window.addEventListener("scroll", aoRolar, { passive: true, capture: true });
      timers.push(setTimeout(() => setPronto(true), 1500));
      timers.push({ fechar: () => { clearTimeout(idleId); window.removeEventListener("scroll", aoRolar, { capture: true }); } });
      timers.push(setTimeout(() => {
        if (cancelado || !alvoRef.current) return;
        tourRolarAte(alvoRef.current, true);
        medir();
      }, 400));
      // Continua remedindo enquanto o balão estiver ativo (imagens carregando, etc.)
      intervalId = setInterval(medir, 200);
    } else {
      // Item não está na tela agora: mostra só o balão, sem travar o tutorial.
      setSemAlvo(true);
      setPronto(true);
    }
    window.addEventListener("resize", medir, { passive: true });
    window.addEventListener("scroll", medir, { passive: true, capture: true });
    return () => {
      cancelado = true;
      timers.forEach((t) => { if (t && t.fechar) t.fechar(); else clearTimeout(t); });;
      if (intervalId) clearInterval(intervalId);
      window.removeEventListener("resize", medir);
      window.removeEventListener("scroll", medir, { capture: true });
    };
  }, [alvoRef]);

  const balaoTexto = (
    <>
      <div style={styles.tourBalaoTexto}>{tr(texto)}</div>
      <div style={styles.tourBalaoRodape}>
        <button style={styles.tourPularBtn} onClick={onPular}>{tr("Pular")}</button>
        {onPularTudo && <button style={styles.tourPularBtn} onClick={onPularTudo} data-testid="pular-tudo">{tr("Pular tudo")}</button>}
        <button style={styles.tourProximoBtn} onClick={onProximo}>{ultimo ? tr("Entendi!") : tr("Próximo")}</button>
      </div>
    </>
  );

  if (semAlvo) {
    return (
      <>
        <div style={styles.tourBackdrop} onClick={onPular} />
        <div style={{ ...styles.tourBalao, left: 16, bottom: 16, top: "auto" }}>{tr(balaoTexto)}</div>
      </>
    );
  }
  if (!rect || rect.width === 0) return null;

  const centerX = rect.left + rect.width / 2;
  const altoTela = window.innerHeight;
  const balaoLeft = Math.max(16, Math.min(centerX - 130, window.innerWidth - 276));
  const altoBalao = balaoRef.current ? balaoRef.current.offsetHeight : 170;
  // Onde cabe o balão: embaixo do item, em cima dele, ou (item enorme) fixo no rodapé.
  const topoEmbaixo = rect.bottom + 46;
  const topoEmCima = rect.top - 46 - altoBalao;
  const cabeEmbaixo = topoEmbaixo + altoBalao <= altoTela - 8;
  const cabeEmCima = topoEmCima >= 34;
  const alvoGrande = rect.height > altoTela * 0.55;
  const modo = alvoGrande ? "fixo" : cabeEmbaixo ? "embaixo" : cabeEmCima ? "emcima" : "fixo";
  const posBalao = modo === "fixo" ? { bottom: 16, top: "auto" } : { top: modo === "embaixo" ? topoEmbaixo : topoEmCima };

  if (!pronto) return null;
  return (
    <>
      <div style={styles.tourBackdrop} onClick={onPular} />
      <div
        data-tour="alvo"
        style={{
          ...styles.tourHighlight,
          top: rect.top - 6,
          left: rect.left - 6,
          width: rect.width + 12,
          height: rect.height + 12,
        }}
      />
      {modo === "fixo" ? tr(null) : modo === "embaixo" ? (
        <div style={{ ...styles.tourSetaBaixo, top: rect.bottom + 10, left: centerX - 15 }}>👆</div>
      ) : (
        <div style={{ ...styles.tourSetaCima, top: rect.top - 40, left: centerX - 15 }}>👇</div>
      )}
      <div ref={balaoRef} style={{ ...styles.tourBalao, left: balaoLeft, ...posBalao }}>{tr(balaoTexto)}</div>
    </>
  );
}

// Progressão de carga automática (regra baseada em desempenho real, sem IA):
// olha os últimos RIR registrados desse exercício e sugere um ajuste concreto
// de carga em cima do último peso usado — mesma lógica de quando "é hora de
// aumentar", só que agora vira um número real em vez de só um aviso.
function sugerirCargaProxima(ultimaCargaKg, rirsRecentes) {
  if (!ultimaCargaKg || isNaN(ultimaCargaKg) || rirsRecentes.length < 2) return null;
  const ultimos = rirsRecentes.slice(-3).map((r) => r.valor);
  const media = ultimos.reduce((s, v) => s + v, 0) / ultimos.length;
  // RIR alto (folgado) nas últimas séries → sugere aumentar ~5%
  if (media >= 3.5) {
    const nova = Math.round(ultimaCargaKg * 1.05 * 2) / 2; // arredonda pro 0.5kg mais próximo
    if (nova > ultimaCargaKg) return { direcao: "subir", valor: nova };
  }
  // RIR muito baixo (na falha) de forma consistente → sugere reduzir ~10% (deload leve)
  if (media <= 0.5 && ultimos.length >= 3) {
    const nova = Math.round(ultimaCargaKg * 0.9 * 2) / 2;
    if (nova < ultimaCargaKg) return { direcao: "descer", valor: nova };
  }
  return null;
}

// Distância entre duas coordenadas (fórmula de Haversine), em km.
function distanciaHaversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const toRad = (v) => (v * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// Treino ao ar livre: cronômetro de corrida/caminhada com GPS real (quando disponível
// e autorizado) medindo distância a cada posição via Haversine, com fallback pra
// distância manual quando o GPS falha, é negado ou o aparelho não suporta.
// Ao finalizar, chama onSalvar(tipo, minutos, distanciaKm, viaGps).
function TreinoArLivreModal({ onFechar, onSalvar }) {
  const [tipo, setTipo] = useState("Caminhada");
  const [rodando, setRodando] = useState(false);
  const [segundos, setSegundos] = useState(0);
  const [distancia, setDistancia] = useState("");
  const [gpsAtivo, setGpsAtivo] = useState(false);
  const [gpsStatus, setGpsStatus] = useState(null); // null | "buscando" | "ok" | "erro"
  const [gpsErroMsg, setGpsErroMsg] = useState("");
  const [distanciaGpsKm, setDistanciaGpsKm] = useState(0);
  const intervaloRef = useRef(null);
  const watchIdRef = useRef(null);
  const ultimaPosRef = useRef(null); // { lat, lon, ts }
  const rodandoRef = useRef(false);

  useEffect(() => { rodandoRef.current = rodando; }, [rodando]);

  useEffect(() => {
    if (rodando) {
      intervaloRef.current = setInterval(() => setSegundos((s) => s + 1), 1000);
    } else if (intervaloRef.current) {
      clearInterval(intervaloRef.current);
      intervaloRef.current = null;
    }
    return () => {
      if (intervaloRef.current) clearInterval(intervaloRef.current);
    };
  }, [rodando]);

  // Liga/desliga o GPS (watchPosition) quando o usuário ativa o toggle.
  useEffect(() => {
    if (!gpsAtivo) {
      if (watchIdRef.current != null && navigator.geolocation) {
        navigator.geolocation.clearWatch(watchIdRef.current);
        watchIdRef.current = null;
      }
      return;
    }
    if (!("geolocation" in navigator)) {
      setGpsStatus("erro");
      setGpsErroMsg("Esse aparelho/navegador não tem suporte a GPS.");
      setGpsAtivo(false);
      return;
    }
    setGpsStatus("buscando");
    ultimaPosRef.current = null;
    setDistanciaGpsKm(0);
    watchIdRef.current = navigator.geolocation.watchPosition(
      (pos) => {
        setGpsStatus("ok");
        const { latitude, longitude, accuracy } = pos.coords;
        // Ignora leituras muito imprecisas (acima de 30m) pra não somar ruído.
        if (accuracy != null && accuracy > 30) return;
        const anterior = ultimaPosRef.current;
        ultimaPosRef.current = { lat: latitude, lon: longitude, ts: pos.timestamp };
        if (!anterior || !rodandoRef.current) return;
        const deltaKm = distanciaHaversineKm(anterior.lat, anterior.lon, latitude, longitude);
        const deltaSeg = (pos.timestamp - anterior.ts) / 1000;
        // Filtro simples contra "pulos" de GPS: ignora deslocamento implausível
        // (mais de 8 m/s ~ 29 km/h, ninguém correndo passa disso de verdade).
        if (deltaSeg > 0 && deltaKm / (deltaSeg / 3600) > 29) return;
        setDistanciaGpsKm((d) => d + deltaKm);
      },
      (err) => {
        setGpsStatus("erro");
        setGpsErroMsg(
          err.code === 1
            ? "Permissão de localização negada. Pode digitar a distância manualmente."
            : "Não consegui pegar o sinal de GPS agora. Pode digitar a distância manualmente."
        );
        setGpsAtivo(false);
      },
      { enableHighAccuracy: true, maximumAge: 2000, timeout: 15000 }
    );
    return () => {
      if (watchIdRef.current != null) {
        navigator.geolocation.clearWatch(watchIdRef.current);
        watchIdRef.current = null;
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [gpsAtivo]);

  const formatarTempo = (totalSegundos) => {
    const min = Math.floor(totalSegundos / 60).toString().padStart(2, "0");
    const seg = (totalSegundos % 60).toString().padStart(2, "0");
    return `${min}:${seg}`;
  };

  const minutosDecorridos = Math.max(1, Math.round(segundos / 60));
  const distanciaManualNum = parseFloat(distancia.replace(",", "."));
  const usandoGps = gpsAtivo || (gpsStatus === "ok" && distanciaGpsKm > 0);
  const [confirmarTreinoCurto, setConfirmarTreinoCurto] = useState(false);

  const finalizarDeVerdade = () => {
    if (watchIdRef.current != null && navigator.geolocation) {
      navigator.geolocation.clearWatch(watchIdRef.current);
      watchIdRef.current = null;
    }
    const distanciaFinal = usandoGps && distanciaGpsKm > 0.01
      ? Math.round(distanciaGpsKm * 100) / 100
      : (isNaN(distanciaManualNum) || distanciaManualNum <= 0 ? null : distanciaManualNum);
    onSalvar(tipo, minutosDecorridos, distanciaFinal, usandoGps && distanciaGpsKm > 0.01);
  };

  const finalizar = () => {
    if (segundos < 10) {
      setConfirmarTreinoCurto(true);
      return;
    }
    finalizarDeVerdade();
  };

  return (
    <>
    <div style={styles.modalOverlay} onClick={onFechar}>
      <div style={styles.modalCard} onClick={(e) => e.stopPropagation()}>
        <button style={styles.modalClose} onClick={onFechar} aria-label={tr("Fechar")}>×</button>
        <div style={styles.eyebrow}>{tr("TREINO AO AR LIVRE")}</div>
        <h2 style={styles.modalTitle}>{tr(tipo)}</h2>

        <div style={styles.chipRow}>
          {["Caminhada", "Corrida"].map((op) => (
            <button
              key={op}
              className="chip"
              disabled={rodando || segundos > 0}
              style={{ ...styles.chip, ...(tipo === op ? styles.chipActive : {}) }}
              onClick={() => setTipo(op)}
            >
              {tr(op)}
            </button>
          ))}
        </div>

        <div style={styles.arLivreCronometro}>{tr(formatarTempo(segundos))}</div>

        {usandoGps && (
          <div style={styles.arLivreGpsDistancia}>
            📍 {tr(distanciaGpsKm.toFixed(2))} {tr("km ")}{gpsStatus === "buscando" && tr("(buscando sinal…)")}
          </div>
        )}

        <div style={{ display: "flex", gap: 10, marginTop: 4 }}>
          {!rodando ? (
            <button style={styles.saveButton} onClick={() => setRodando(true)}>
              {segundos === 0 ? tr("▶ Começar") : tr("▶ Retomar")}
            </button>
          ) : (
            <button style={styles.saveButton} onClick={() => setRodando(false)}>{tr("⏸ Pausar")}</button>
          )}
        </div>

        {segundos === 0 && (
          <button
            style={{ ...styles.arLivreGpsToggle, ...(gpsAtivo ? styles.arLivreGpsToggleAtivo : {}) }}
            onClick={() => setGpsAtivo((v) => !v)}
          >
            {gpsAtivo ? tr("📍 GPS ativado — usar distância manual") : tr("📍 Usar GPS pra medir a distância")}
          </button>
        )}
        {gpsStatus === "erro" && <p style={styles.arLivreGpsErro}>{tr(gpsErroMsg)}</p>}

        {!usandoGps && (
          <label style={{ ...styles.avalField, marginTop: 18 }}>
            {tr("Distância percorrida (km) — opcional")}<input
              type="text"
              inputMode="decimal"
              placeholder={tr("Ex: 3,5")}
              value={distancia}
              onChange={(e) => setDistancia(e.target.value)}
              style={styles.avalInput}
            />
          </label>
        )}

        <button
          style={{ ...styles.saveButton, ...(segundos > 0 ? {} : { opacity: 0.5, cursor: "not-allowed" }) }}
          disabled={segundos === 0}
          onClick={finalizar}
        >
          {tr("✅ Finalizar e salvar")}</button>
        <p style={styles.modalDisclaimer}>
          {usandoGps
            ? tr("Distância medida por GPS. Calorias estimadas com base no tempo, tipo de atividade e distância percorrida.")
            : tr("Calorias estimadas com base no tempo e no tipo de atividade. Fica salvo no seu histórico normalmente.")}
        </p>
      </div>
    </div>
      {confirmarTreinoCurto && (
        <ConfirmModal
          mensagem="Menos de 10 segundos de treino — quer registrar mesmo assim?"
          textoConfirmar="Registrar"
          onCancelar={() => setConfirmarTreinoCurto(false)}
          onConfirmar={() => { setConfirmarTreinoCurto(false); finalizarDeVerdade(); }}
        />
      )}
    </>
  );
}

function CronometroRapidoRotina({ onIniciarDescanso }) {
  const [modo, setModo] = useState("relogio"); // "relogio" | "opcoes"
  const [agora, setAgora] = useState(() => new Date());

  useEffect(() => {
    const id = setInterval(() => setAgora(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  const horaBrasilia = new Intl.DateTimeFormat(localeAtual(), {
    timeZone: "America/Sao_Paulo",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).format(agora);

  return (
    <section style={styles.cronoRapidoCard}>
      <div style={styles.cronoRapidoLinha}>
        {modo === "relogio" ? (
          <div style={styles.cronoRapidoRelogioBloco}>
            <div style={styles.cronoRapidoHora}>{tr(horaBrasilia)}</div>
            <div style={styles.cronoRapidoHoraLabel}>{tr("Horário de Brasília")}</div>
          </div>
        ) : (
          <div style={styles.cronoRapidoOpcoesRow}>
            {["1 min", "1:30 min", "2 min", "2:30 min", "3 min", "5 min"].map((op) => (
              <button
                key={op}
                className="chip"
                style={styles.cronoRapidoBtn}
                onClick={() => {
                  onIniciarDescanso(op, "Cronômetro");
                  setModo("relogio");
                }}
              >
                {tr(op.replace(" min", ""))}
              </button>
            ))}
          </div>
        )}

        <button
          style={styles.cronoRapidoToggleBtn}
          onClick={() => setModo((m) => (m === "relogio" ? "opcoes" : "relogio"))}
          aria-label={modo === "relogio" ? tr("Abrir cronômetro") : tr("Ver relógio")}
          title={modo === "relogio" ? tr("Cronômetro") : tr("Ver relógio")}
        >
          {modo === "relogio" ? tr("⏱️") : tr("🕐")}
        </button>
      </div>
    </section>
  );
}

function DayCard({ entry, onFoco, onPeriodo, onAddExercicio, onRemoveExercicio, onEditExercicio, onEditCargaSerie, onEditRirSerie, onAddExercicioPersonalizado, onEscolherExercicio, exerciciosFavoritos, onToggleFavorito, onDuplicarDia, cargaHistorico, rirHistorico, notasExercicio, onEditNotaExercicio, onEditCardio, onAdicionarCardioFinal, onRemoverCardioFinal, onAbrirExercicio, onIniciarDescanso, onTrocarExercicio, onConcluirTreino, onRegistrarDor, onIniciarGuiado, progressao, dores, recordes, restricoesFisicas, refsTour }) {
  const { dia, foco, cardio, exercicios, periodo } = entry;
  const isDescanso = foco === "Descanso";
  const isCardio = foco === "Cardio";
  const podeAdicionar = !isDescanso && !isCardio && (LIBRARY[foco] || []).length > exercicios.length;
  const [modalCalc, setModalCalc] = useState(null); // { tipo: "1rm"|"anilhas", cargaInicial, repsInicial }
  const [buscaExercicioAberta, setBuscaExercicioAberta] = useState(null); // id do exercício sendo trocado por busca
  const [duplicarAberto, setDuplicarAberto] = useState(false);
  const [modalFocoAberto, setModalFocoAberto] = useState(false);
  const [personalizadoAberto, setPersonalizadoAberto] = useState(false);

  return (
    <>
    <div style={styles.dayCard}>
      <div style={styles.dayCardBody}>
        <div style={styles.dayCardTop}>
          <div>
            <div style={styles.dayName}>{tr(dia)}</div>
            <div style={styles.focoLabel}>{tr("Trocar foco do dia:")}</div>
            <button style={styles.selectFocoDia} onClick={() => setModalFocoAberto(true)} ref={refsTour ? refsTour.foco : undefined}>
              {tr(foco)} <span style={styles.selectFocoDiaSeta}>▾</span>
            </button>
          </div>
          <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 6 }}>
            <div style={styles.focoTag}>{tr(foco)}</div>
            {!isDescanso && exercicios.length > 0 && (
              <button style={{ ...styles.trocarBtn, fontSize: 11 }} onClick={() => setDuplicarAberto(true)} title={tr("Duplicar esse treino pra outro dia")} ref={refsTour ? refsTour.duplicar : undefined}>
                {tr("📋 Duplicar")}</button>
            )}
          </div>
        </div>

        {!isDescanso && (
          <div style={{ marginTop: 8 }} ref={refsTour ? refsTour.periodo : undefined}>
            <div style={styles.focoLabel}>{tr("🔔 Notificar treino:")}</div>
            <div style={styles.chipRow}>
              {PERIODOS_TREINO.map((p) => (
                <button
                  key={p}
                  className="chip"
                  onClick={() => onPeriodo(p)}
                  style={{ ...styles.chip, ...((periodo || "Manhã") === p ? styles.chipActive : {}) }}
                >
                  {tr(p)} ({tr(HORARIO_POR_PERIODO[p])})
                </button>
              ))}
            </div>
          </div>
        )}

        {isDescanso && <div style={styles.restNote}>{tr("Dia de descanso. O músculo cresce na recuperação, não pula essa parte.")}</div>}

        {isCardio && cardio && (
          <div style={styles.cardioBlock}>
            <div style={styles.cardioVideoRow}>
              {(() => {
                const thumb = getThumbnailCardio(cardio.tipo);
                return thumb ? (
                  <img
                    src={thumb}
                    alt={trt("Capa do vídeo de {0}", [cardio.tipo])}
                    style={styles.exThumb}
                    loading="lazy"
                    onClick={() => window.open(getVideoCardioUrl(cardio.tipo), "_blank")}
                    onError={(e) => { e.target.style.display = "none"; }}
                  />
                ) : null;
              })()}
              <button
                style={styles.guiadoVerBtnMini}
                onClick={() => window.open(getVideoCardioUrl(cardio.tipo), "_blank")}
              >
                ▶ {VIDEOS_CARDIO[cardio.tipo] ? tr("Assistir execução") : tr("Ver forma correta no YouTube")}
              </button>
            </div>
            <label style={styles.fieldLabel}>
              {tr("Tipo")}<div style={styles.cardioTipoRow}>
                <select value={cardio.tipo} onChange={(e) => onEditCardio("tipo", e.target.value)} style={styles.selectSmall}>
                  {CARDIO_TIPOS.map((t) => (
                    <option key={t} value={t}>{tr(t)}</option>
                  ))}
                </select>
                <button
                  style={styles.trocarCardioBtn}
                  onClick={() => {
                    const idx = CARDIO_TIPOS.indexOf(cardio.tipo);
                    const proximo = CARDIO_TIPOS[(idx + 1) % CARDIO_TIPOS.length];
                    onEditCardio("tipo", proximo);
                  }}
                  aria-label={tr("Trocar tipo de cardio")}
                  title={tr("Trocar cardio")}
                >
                  🔄
                </button>
              </div>
            </label>
            <div style={styles.cardioDuracaoIntensidadeRow}>
              <label style={{ ...styles.fieldLabel, flex: 1 }}>
                {tr("Duração (min)")}<input
                  type="number"
                  min={5}
                  max={120}
                  value={cardio.duracao}
                  onChange={(e) => onEditCardio("duracao", Number(e.target.value))}
                  style={{ ...styles.inputSmall, width: "100%" }}
                />
              </label>
              <label style={{ ...styles.fieldLabel, flex: 1 }}>
                {tr("Intensidade")}<select value={cardio.intensidade} onChange={(e) => onEditCardio("intensidade", e.target.value)} style={styles.selectSmall}>
                  <option>{tr("Leve")}</option>
                  <option>{tr("Moderada")}</option>
                  <option>{tr("Intensa")}</option>
                </select>
              </label>
            </div>
          </div>
        )}

        {!isDescanso && !isCardio && (
          <div>
            <div style={styles.aquecimentoBox}>
              {tr("🔥 Aquecimento sugerido: 5 min de cardio leve + mobilidade articular antes da primeira série.")}</div>
            {exercicios.map((ex, idx) => (
              <div key={ex.id} style={ex.concluido ? { ...styles.exRow, ...styles.exRowConcluido } : styles.exRow}>
                <div style={styles.exHeaderNovo} ref={idx === 0 && refsTour ? refsTour.cabecalho : undefined}>
                  <button
                    style={styles.exRingWrap(ex.concluido)}
                    onClick={() => onEditExercicio(ex.id, "concluido", !ex.concluido)}
                    aria-label={ex.concluido ? trt("Marcar {0} como não concluído", [ex.name]) : trt("Marcar {0} como concluído", [ex.name])}
                    title={ex.concluido ? tr("Concluído — toque para desmarcar") : tr("Marcar como concluído")}
                  >
                    <span style={styles.exRingInner}>{ex.concluido ? tr("✓") : tr("")}</span>
                  </button>
                  <button
                    style={styles.exNameBtnGrande}
                    onClick={() => onAbrirExercicio(ex)}
                    aria-label={trt("Ver como executar {0}", [ex.name])}
                    ref={idx === 0 && refsTour ? refsTour.video : undefined}
                  >
                    {tr(ex.name)}
                  </button>
                  {exercicioTemRisco(ex.name, restricoesFisicas) && (
                    <span style={styles.exRiscoTag} title={tr("Você marcou essa região como sensível no seu perfil")}>
                      {tr("⚠️ Atenção: ")}{tr(exercicioTemRisco(ex.name, restricoesFisicas))}
                    </span>
                  )}
                  <div style={styles.exAcoesMini}>
                    <button
                      style={styles.exAcaoMiniBtn}
                      onClick={() => onRegistrarDor(ex.name)}
                      aria-label={trt("Registrar dor ou desconforto em {0}", [ex.name])}
                      title={tr("Registrar dor/desconforto")}
                    >
                      ⚠️
                    </button>
                    <button onClick={() => onRemoveExercicio(ex.id)} style={styles.exAcaoMiniBtn} aria-label={trt("Remover {0}", [ex.name])} title={tr("Remover exercício")}>
                      ×
                    </button>
                  </div>
                </div>

                {(() => {
                  const ultimaDor = getUltimaDorRelacionada(ex.name, dores);
                  if (!ultimaDor) return null;
                  return (
                    <div style={styles.dorAlertBox}>
                      ⚠️ {ultimaDor.mesmoGrupo
                        ? trt("Dor registrada recentemente em \"{0}\" (mesmo grupo muscular)", [ultimaDor.exercicio])
                        : tr("Você já registrou dor/desconforto nesse exercício antes")}
                      {tr(" ")}— {tr(new Date(ultimaDor.data + "T00:00:00").toLocaleDateString(localeAtual()))}
                      {ultimaDor.nota ? tr(`: "${ultimaDor.nota}"`) : tr("")}
                    </div>
                  );
                })()}

                <div style={styles.maquinaTrocarRow}>
                  {ex.maquinas.length > 1 ? (
                    <select
                      value={ex.maquina}
                      onChange={(e) => onEditExercicio(ex.id, "maquina", e.target.value)}
                      style={{ ...styles.machineSelect, width: "auto", flex: 1, minWidth: 0, marginBottom: 0 }}
                      ref={idx === 0 && refsTour ? refsTour.maquina : undefined}
                    >
                      {ex.maquinas.map((m) => (
                        <option key={m} value={m}>{tr(m)}</option>
                      ))}
                    </select>
                  ) : (
                    <div style={{ ...styles.machineFixed, marginBottom: 0 }} ref={idx === 0 && refsTour ? refsTour.maquina : undefined}>{tr(ex.maquinas[0])}</div>
                  )}
                  <button style={styles.trocarBtn} onClick={() => onTrocarExercicio(ex.id)} title={tr("Trocar exercício")} ref={idx === 0 && refsTour ? refsTour.trocar : undefined}>
                    {tr("🔄 Trocar")}</button>
                  <button style={{ ...styles.trocarBtn, marginLeft: 6 }} onClick={() => setBuscaExercicioAberta(ex.id)} title={tr("Buscar exercício por nome")}>
                    🔍
                  </button>
                </div>
                {(() => {
                  const thumb = getThumbnailExercicio(ex);
                  if (!thumb) return null;
                  return (
                    <div style={styles.exThumbGrandeWrap} onClick={() => onAbrirExercicio(ex)}>
                      <img
                        src={thumb}
                        alt={trt("Capa do vídeo de {0}", [ex.name])}
                        style={styles.exThumbGrande}
                        loading="lazy"
                        onError={(e) => { e.target.parentElement.style.display = "none"; }}
                      />
                      <div style={styles.exThumbGrandePlayBadge}>{tr("▶ Ver execução")}</div>
                    </div>
                  );
                })()}

                <div style={styles.novoCamposRow} ref={idx === 0 && refsTour ? refsTour.seriesReps : undefined}>
                  <div style={styles.novoCampoBloco}>
                    <span style={styles.novoCampoLabel}>{tr("Séries")}</span>
                    <div style={styles.setsStepperNovo}>
                      <button
                        type="button"
                        onClick={() => onEditExercicio(ex.id, "sets", Math.max(1, (Number(ex.sets) || 1) - 1))}
                        style={styles.stepperBtnNovo}
                        aria-label={trt("Diminuir número de séries de {0}", [ex.name])}
                      >
                        −
                      </button>
                      <input
                        type="number"
                        inputMode="numeric"
                        value={ex.sets}
                        min={1}
                        max={10}
                        onFocus={(e) => e.target.select()}
                        onChange={(e) => onEditExercicio(ex.id, "sets", e.target.value === "" ? "" : Number(e.target.value))}
                        onBlur={(e) => {
                          const v = Number(e.target.value);
                          onEditExercicio(ex.id, "sets", Number.isFinite(v) && v > 0 ? Math.min(10, v) : 1);
                        }}
                        style={styles.numMiniNovo}
                      />
                      <button
                        type="button"
                        onClick={() => onEditExercicio(ex.id, "sets", Math.min(10, (Number(ex.sets) || 0) + 1))}
                        style={styles.stepperBtnNovo}
                        aria-label={trt("Aumentar número de séries de {0}", [ex.name])}
                      >
                        +
                      </button>
                    </div>
                  </div>
                  <div style={styles.novoCampoBloco}>
                    <span style={styles.novoCampoLabel}>{tr("Repetições")}</span>
                    <input
                      type="text"
                      value={ex.reps}
                      onChange={(e) => onEditExercicio(ex.id, "reps", e.target.value)}
                      style={styles.novoInputBox}
                    />
                  </div>
                </div>

                <div style={styles.cargaSeriesBox} ref={idx === 0 && refsTour ? refsTour.cargaSeries : undefined}>
                  <div style={styles.cargaSeriesTitulo}>
                    {tr("Carga por série")}{recordes && recordes[ex.name] && (
                      <span style={styles.recordeTag}>{tr("🏆 Recorde: ")}{tr(recordes[ex.name].texto)}</span>
                    )}
                    {progressao && progressao[ex.name] > 0 && progressao[ex.name] % 3 === 0 && (
                      <span style={styles.progressaoTag}>{tr("🔺 Hora de aumentar a carga")}</span>
                    )}
                  </div>
                  {(() => {
                    const historicoEx = (cargaHistorico && cargaHistorico[ex.name]) || [];
                    if (historicoEx.length === 0) return null;
                    const ultimo = historicoEx[historicoEx.length - 1];
                    const rirsEx = (rirHistorico && rirHistorico[ex.name]) || [];
                    const sugestao = sugerirCargaProxima(Number(ultimo.valor), rirsEx);
                    return (
                      <>
                        <div style={{ fontSize: 12, opacity: 0.75, marginBottom: sugestao ? 2 : 6, wordBreak: "break-word", overflowWrap: "anywhere" }}>
                          {tr("Última vez: ")}{tr(ultimo.valor)}{tr("kg (")}{tr(new Date(ultimo.data + "T00:00:00").toLocaleDateString(localeAtual()))})
                        </div>
                        {sugestao && (
                          <div style={styles.sugestaoCargaTag}>
                            {sugestao.direcao === "subir"
                              ? trt("💡 Sugestão pra hoje: {0}kg (seus últimos RIR estavam folgados)", [sugestao.valor])
                              : trt("💡 Sugestão pra hoje: {0}kg (últimos RIR na falha — considere aliviar)", [sugestao.valor])}
                          </div>
                        )}
                      </>
                    );
                  })()}
                  <div style={styles.cargaSeriesGrid}>
                    {Array.from({ length: ex.sets || 1 }, (_, i) => {
                      const cargasAtual = ex.cargas && ex.cargas.length === (ex.sets || 1) ? ex.cargas : Array.from({ length: ex.sets || 1 }, (_, j) => (ex.cargas && ex.cargas[j]) || ex.carga || "");
                      const rirsAtual = ex.rirs && ex.rirs.length === (ex.sets || 1) ? ex.rirs : Array.from({ length: ex.sets || 1 }, () => "");
                      return (
                        <div key={i} style={styles.cargaSerieItem}>
                          <span style={styles.cargaSerieNum}>{tr("Série ")}{tr(i + 1)}</span>
                          <input
                            type="text"
                            value={cargasAtual[i] || ""}
                            placeholder={tr("ex: 20kg")}
                            onChange={(e) => onEditCargaSerie(ex.id, i, e.target.value)}
                            style={styles.novoInputBox}
                          />
                          <select
                            value={rirsAtual[i] || ""}
                            onChange={(e) => onEditRirSerie(ex.id, i, e.target.value)}
                            style={{ ...styles.selectSmall, marginTop: 4 }}
                            title={tr("RIR — repetições que ainda sobrariam no tanque")}
                          >
                            <option value="">{tr("RIR")}</option>
                            {[0, 1, 2, 3, 4, 5].map((n) => (
                              <option key={n} value={n}>{tr("RIR ")}{tr(n)}</option>
                            ))}
                          </select>
                        </div>
                      );
                    })}
                  </div>
                  <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 8 }} ref={idx === 0 && refsTour ? refsTour.calcBtns : undefined}>
                    <button
                      style={styles.trocarBtn}
                      onClick={() => {
                        const cargaBase = (ex.cargas && ex.cargas[0]) || ex.carga || "";
                        const numero = extrairNumeroCarga(cargaBase);
                        const repsBase = parseInt(ex.reps, 10) || 10;
                        setModalCalc({ tipo: "1rm", cargaInicial: numero || "", repsInicial: repsBase });
                      }}
                    >
                      {tr("🧮 1RM")}</button>
                    <button
                      style={styles.trocarBtn}
                      onClick={() => {
                        const cargaBase = (ex.cargas && ex.cargas[0]) || ex.carga || "";
                        const numero = extrairNumeroCarga(cargaBase);
                        setModalCalc({ tipo: "anilhas", cargaInicial: numero || "" });
                      }}
                    >
                      {tr("🏋️ Anilhas")}</button>
                    <button
                      style={styles.trocarBtn}
                      onClick={() => {
                        const cargaBase = (ex.cargas && ex.cargas[0]) || ex.carga || "";
                        const numero = extrairNumeroCarga(cargaBase);
                        const repsBase = parseInt(ex.reps, 10) || 10;
                        setModalCalc({ tipo: "aquecimento", cargaInicial: numero || "", repsInicial: repsBase });
                      }}
                    >
                      {tr("🔥 Aquecimento")}</button>
                  </div>
                  <div style={styles.cargaSeriesDica}>
                    {tr("Diferente em cada série? Ajuste aqui — no treino guiado, a carga certa aparece automaticamente quando você mudar de série.")}</div>
                  <textarea
                    value={(notasExercicio && notasExercicio[ex.name]) || ""}
                    onChange={(e) => onEditNotaExercicio(ex.name, e.target.value)}
                    placeholder={tr("📝 Anotação sobre esse exercício (pegada, ajuste do banco, dor, etc.)")}
                    style={styles.notaExercicioBox}
                    rows={2}
                    ref={idx === 0 && refsTour ? refsTour.nota : undefined}
                  />
                </div>

                <div style={styles.novoRodapeRow}>
                  <div style={styles.novoCampoBloco} ref={idx === 0 && refsTour ? refsTour.descanso : undefined}>
                    <span style={styles.novoCampoLabel}>{tr("DESCANSO")}</span>
                    {ex.superset && (
                      <div style={{ fontSize: 11, opacity: 0.8, marginBottom: 4 }}>{tr("🔗 Superset — sem descanso pro próximo exercício")}</div>
                    )}
                    {ex.dropset && (
                      <div style={{ fontSize: 11, opacity: 0.8, marginBottom: 4 }}>{tr("⬇️ Dropset — sem descanso entre as séries")}</div>
                    )}
                    <div style={styles.novoDescansoBox}>
                      <select
                        value={ex.descanso}
                        onChange={(e) => onEditExercicio(ex.id, "descanso", e.target.value)}
                        style={styles.novoDescansoSelect}
                      >
                        {DESCANSO_OPCOES.map((r) => (
                          <option key={r} value={r}>{tr(r)}</option>
                        ))}
                      </select>
                      <button
                        style={styles.startTimerBtn}
                        onClick={() => onIniciarDescanso(ex.descanso, ex.name)}
                        aria-label={trt("Iniciar descanso de {0}", [ex.name])}
                      >
                        ▶
                      </button>
                    </div>
                  </div>
                  <button
                    style={styles.trocarToggleNovo}
                    onClick={() => onTrocarExercicio(ex.id)}
                    aria-label={trt("Trocar {0} por outro exercício", [ex.name])}
                    title={tr("Trocar exercício")}
                  >
                    <span>{tr("Trocar")}</span>
                    <span style={styles.trocarToggleKnob}>
                      <span style={styles.trocarToggleBall} />
                    </span>
                  </button>
                </div>
              </div>
            ))}

            {exercicios.length === 0 && <div style={styles.restNote}>{tr("Nenhum exercício adicionado ainda.")}</div>}
            {podeAdicionar && (
              <button onClick={onAddExercicio} style={styles.addBtn} ref={refsTour ? refsTour.adicionar : undefined}>
                {tr("+ adicionar exercício de ")}{tr(foco.toLowerCase())}
              </button>
            )}
            <button
              onClick={() => setPersonalizadoAberto(true)}
              style={{ ...styles.addBtn, marginTop: 8, opacity: 0.85 }}
              ref={refsTour ? refsTour.personalizado : undefined}
            >
              {tr("+ exercício personalizado")}</button>
          </div>
        )}

        {!isDescanso && !isCardio && exercicios.length > 0 && cardio && (
          <div style={styles.cardioBlock} ref={refsTour ? refsTour.cardio : undefined}>
            <div style={styles.cardLabel}>{tr("🏃 Cardio no final do treino")}</div>
            <div style={styles.cardioVideoRow}>
              {(() => {
                const thumb = getThumbnailCardio(cardio.tipo);
                return thumb ? (
                  <img
                    src={thumb}
                    alt={trt("Capa do vídeo de {0}", [cardio.tipo])}
                    style={styles.exThumb}
                    loading="lazy"
                    onClick={() => window.open(getVideoCardioUrl(cardio.tipo), "_blank")}
                    onError={(e) => { e.target.style.display = "none"; }}
                  />
                ) : null;
              })()}
              <button
                style={styles.guiadoVerBtnMini}
                onClick={() => window.open(getVideoCardioUrl(cardio.tipo), "_blank")}
              >
                ▶ {VIDEOS_CARDIO[cardio.tipo] ? tr("Assistir execução") : tr("Ver forma correta no YouTube")}
              </button>
            </div>
            <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "flex-end" }}>
              <label style={styles.fieldLabel}>
                {tr("Tipo")}<select value={cardio.tipo} onChange={(e) => onEditCardio("tipo", e.target.value)} style={styles.selectSmall}>
                  {CARDIO_TIPOS.map((tp) => (
                    <option key={tp} value={tp}>{tr(tp)}</option>
                  ))}
                </select>
              </label>
              <label style={styles.fieldLabel}>
                {tr("Duração (min)")}<input
                  type="number"
                  min={5}
                  max={60}
                  value={cardio.duracao}
                  onChange={(e) => onEditCardio("duracao", Number(e.target.value))}
                  style={styles.inputSmall}
                />
              </label>
              <label style={styles.fieldLabel}>
                {tr("Intensidade")}<select value={cardio.intensidade} onChange={(e) => onEditCardio("intensidade", e.target.value)} style={styles.selectSmall}>
                  <option>{tr("Leve")}</option>
                  <option>{tr("Moderada")}</option>
                  <option>{tr("Intensa")}</option>
                </select>
              </label>
              <button style={styles.trocarCardioBtn} onClick={onRemoverCardioFinal} title={tr("Remover cardio do final do treino")}>
                {tr("Remover")}</button>
            </div>
          </div>
        )}

        {!isDescanso && !isCardio && exercicios.length > 0 && !cardio && (
          <button onClick={onAdicionarCardioFinal} style={styles.addBtn} ref={refsTour ? refsTour.cardio : undefined}>
            {tr("+ adicionar cardio no final do treino")}</button>
        )}

        {!isDescanso && exercicios.length > 0 && (
          <button style={styles.guiadoBtn} onClick={() => onIniciarGuiado(entry)} ref={refsTour ? refsTour.guiado : undefined}>
            {tr("▶ Iniciar treino guiado")}</button>
        )}

        {!isDescanso && (
          <button style={styles.concluirBtn} onClick={onConcluirTreino} ref={refsTour ? refsTour.concluir : undefined}>
            {tr("✓ Concluir treino de hoje")}</button>
        )}
      </div>
    </div>
    {modalCalc && modalCalc.tipo === "1rm" && (
      <Calc1RMModal cargaInicial={modalCalc.cargaInicial} repsInicial={modalCalc.repsInicial} onClose={() => setModalCalc(null)} />
    )}
    {modalCalc && modalCalc.tipo === "anilhas" && (
      <CalcAnilhasModal cargaInicial={modalCalc.cargaInicial} onClose={() => setModalCalc(null)} />
    )}
    {modalCalc && modalCalc.tipo === "aquecimento" && (
      <AquecimentoModal cargaInicial={modalCalc.cargaInicial} repsInicial={modalCalc.repsInicial} onClose={() => setModalCalc(null)} />
    )}
    {buscaExercicioAberta && (() => {
      const exAtual = exercicios.find((e) => e.id === buscaExercicioAberta);
      const usados = new Set(exercicios.map((e) => e.name));
      if (exAtual) usados.delete(exAtual.name);
      const candidatos = (LIBRARY[foco] || []).filter((o) => !usados.has(o.name));
      return (
        <BuscarExercicioModal
          candidatos={candidatos}
          favoritos={exerciciosFavoritos || []}
          onToggleFavorito={onToggleFavorito}
          onEscolher={(nome) => {
            onEscolherExercicio(buscaExercicioAberta, nome);
            setBuscaExercicioAberta(null);
          }}
          onClose={() => setBuscaExercicioAberta(null)}
        />
      );
    })()}
    {personalizadoAberto && (
      <ExercicioPersonalizadoModal
        onSalvar={(nome, maquina) => {
          onAddExercicioPersonalizado(nome, maquina);
          setPersonalizadoAberto(false);
        }}
        onFechar={() => setPersonalizadoAberto(false)}
      />
    )}
    {duplicarAberto && (
      <DuplicarDiaModal
        diaOrigem={dia}
        diasDisponiveis={DIAS_SEMANA.filter((d) => d !== dia)}
        onEscolher={(diaDestino) => {
          onDuplicarDia(diaDestino);
          setDuplicarAberto(false);
        }}
        onClose={() => setDuplicarAberto(false)}
      />
    )}
    {modalFocoAberto && (
      <TrocarFocoModal
        focoAtual={foco}
        onEscolher={(f) => {
          onFoco(f);
          setModalFocoAberto(false);
        }}
        onFechar={() => setModalFocoAberto(false)}
      />
    )}
    </>
  );
}

